function activeSmartCascadeCount(){ return smartCascadeRuns.size; }
function smartCascadeRunForLoop(loopId){ return loopId ? smartCascadeRuns.get(loopId) || null : null; }
function smartCascadeIsLoopRunning(loopId){ return Boolean(smartCascadeRunForLoop(loopId)); }
function syncSmartCascadeLegacyState(preferredLoopId=''){
    const activeIds = [...smartCascadeRuns.keys()];
    smartCascadeRunning = activeIds.length > 0;
    smartCascadeActiveLoopId = preferredLoopId && smartCascadeRuns.has(preferredLoopId)
        ? preferredLoopId
        : (activeIds[0] || '');
    const activeRun = smartCascadeActiveLoopId ? smartCascadeRuns.get(smartCascadeActiveLoopId) : null;
    smartCascadeStopRequested = Boolean(activeRun?.stopRequested);
    smartCascadeRunPath = activeRun?.runPath || null;
}
function smartCascadeAnyRunning(){ return smartCascadeRunning || activeSmartCascadeCount() > 0; }
function smartCascadeEdgeState(edgeKey){
    for(const run of smartCascadeRuns.values()){
        const state = run?.runPath?.states?.[edgeKey];
        if(state) return state;
    }
    return smartCascadeRunPath?.states?.[edgeKey] || '';
}
function smartCascadePathForCtx(ctx=null){
    return ctx?.runState?.runPath || ctx?.runPath || smartCascadeRunPath;
}
function capturePendingUndo(){ pendingUndoSnapshot = snapshotForUndo(); }
function commitPendingUndo(){
    if(!pendingUndoSnapshot) return;
    XiaomeiHistoryKernel.push(undoStack, redoStack, pendingUndoSnapshot, UNDO_LIMIT, true);
    pendingUndoSnapshot = null;
    return;

}
function discardPendingUndo(){ pendingUndoSnapshot = null; }
function snapshotForUndo(){
    return {
        nodes:XiaomeiHistoryKernel.cloneData(nodes),
        connections:XiaomeiHistoryKernel.cloneData(canvas?.connections || []),
        selectedId,
        selectedIds:selectedIds.slice(),
        selectedImage:{...selectedImage},
        composerReferences:window.CanvasAgentReferenceBridge?.snapshot()
    };

}
function pushUndo(){
    if(undoSuppressed || !canvas) return;
    XiaomeiHistoryKernel.push(undoStack, redoStack, snapshotForUndo(), UNDO_LIMIT, true);
    return;

}
function performUndo(){
    const snap = XiaomeiHistoryKernel.undo(undoStack, redoStack, snapshotForUndo());
    if(!snap){ toast(tr('smart.toastNoUndo')); return; }
    restoreSmartUndoSnapshot(snap);
    toast(tr('smart.toastUndone'));
    return;

}
function performRedo(){
    const snap = XiaomeiHistoryKernel.redo(undoStack, redoStack, snapshotForUndo());
    if(!snap){ toast('没有可重做的操作'); return; }
    restoreSmartUndoSnapshot(snap);
    toast('已重做');
    return;

}
function restoreSmartUndoSnapshot(snap){
    undoSuppressed = true;
    const currentById = new Map(nodes.map(node => [node.id, node]));
    nodes = preserveSmartBatchPromptRequests(snap.nodes.map(node => {
        const current = currentById.get(node.id);
        if(!current || !smartNodeInFlight(node)) return node;
        const merged = {...node, images:mergeSmartImageLists(node.images, current.images)};
        if(smartNodeHasCompletedResult(current)){
            merged.runFinishedAt = current.runFinishedAt;
            merged.title = current.title;
            markSmartNodeComplete(merged);
        } else if(smartPendingTasks(current).length){
            merged.pendingTasks = JSON.parse(JSON.stringify(current.pendingTasks));
            merged.pending = smartPendingTasks(merged).length;
            merged.running = false;
        } else if(current.runError && !smartNodeInFlight(current)){
            markSmartNodeFailed(merged, current.runError);
        }
        return merged;
    }));
    if(canvas) canvas.connections = snap.connections;
    selectedId = snap.selectedId;
    selectedIds = snap.selectedIds;
    selectedImage = snap.selectedImage;
    window.CanvasAgentReferenceBridge?.restore(snap.composerReferences);
    activeComposerSubject = null;
    lastComposerNodeId = '';
    recoverStuckOutputsFromLogs();
    render();
    scheduleSave();
    undoSuppressed = false;
    // 撤销可能恢复生成中的快照；已完成的请求必须按原任务号重新收取结果。
    if(!sharedCanvasMode){
        resumeSmartPendingTasks();
        resumeJimengPendingNodes();
    }
}
