        const src = img.getAttribute('src');
        if(!state || state.original !== original){
            state = {original, src, pixels:Math.max(img.naturalWidth, img.naturalHeight) || 512, failed:new Set()};
            smartCanvasImageResolutions.set(img, state);
        }
