function createComfyWorkflowNodeAt(point, payload={}, options={}){
    const workflowRef = String(payload.workflow_ref || payload.workflowRef || '').trim();
    if(!workflowRef) return null;
    const workflowTitle = String(payload.workflow_title || payload.workflowTitle || workflowRef.replace(/\.json$/i, '') || 'ComfyUI 工作流').trim();
    const fields = Array.isArray(payload.fields) ? JSON.parse(JSON.stringify(payload.fields)) : [];
    const readiness = payload.readiness && typeof payload.readiness === 'object' ? JSON.parse(JSON.stringify(payload.readiness)) : {};
    const current = cloneSmartSettings(settings || canvasDefaultSmartSettings || initialSmartSettings);
    current.engine = 'comfy';
    current.comfyMode = 'custom';
    current.comfyWorkflow = workflowRef;
    current.comfyAppId = String(payload.app_id || payload.appId || '').trim();
    current.comfyWorkflowTitle = workflowTitle;
    current.comfyWorkflowFields = fields;
    current.comfyParams = current.comfyParams && typeof current.comfyParams === 'object' ? current.comfyParams : {};
    fields.forEach(field => {
        if(field?.id && current.comfyParams[field.id] === undefined && field.default !== undefined){
            current.comfyParams[field.id] = field.default;
        }
    });
    const node = createNode(
        (point?.x || 0) - 195,
        (point?.y || 0) - 119,
        [],
        {
            ...options,
            nodeType:SMART_COMFY_WORKFLOW_NODE_TYPE,
            title:workflowTitle,
            w:430,
            h:comfyWorkflowNodeDefaultHeight(fields)
        }
    );
    if(!node) return null;
    node.workflowRef = workflowRef;
    node.workflowTitle = workflowTitle;
    node.workflowDescription = String(payload.workflow_description || payload.workflowDescription || '').trim();
    node.workflowSource = String(payload.workflow_source || payload.workflowSource || '').trim();
    node.workflowAppId = String(payload.app_id || payload.appId || '').trim();
    node.workflowFields = fields;
    node.workflowReadiness = readiness;
    node.workflowStatus = readiness.can_run === true ? 'ready' : (String(readiness.workflow_status || '').trim() || 'needs_preparation');
    node.runSettings = settingsForStorage(current);
    node.title = workflowTitle;
    node.comfyAutoSize = true;
    normalizeSmartComfyWorkflowNode(node);
    comfyWorkflowCache[workflowRef] = {
        name:workflowRef,
        config:{title:workflowTitle, fields},
        builtin:false,
        _canvasFallback:true
    };
    return node;
}
function createComfyWorkflowNodeFromCatalog(point, workflowName=''){
    const requested = String(workflowName || '').trim();
    const entry = (comfyWorkflows || []).find(item => item?.name === requested)
        || (requested ? null : (comfyWorkflows || [])[0]);
    if(!entry?.name){
        toast('请先在 ComfyUI 工作台导入或配置工作流');
        return null;
    }
    const node = createComfyWorkflowNodeAt(point, {
        workflow_ref:entry.name,
        workflow_title:entry.title || entry.name.replace(/\.json$/i, ''),
        workflow_description:entry.description || '',
        workflow_source:entry.sourceKind || 'workflow-library',
        app_id:entry.appId || '',
        fields:Array.isArray(entry.fields) ? entry.fields : [],
        readiness:entry.readiness && typeof entry.readiness === 'object' ? entry.readiness : {}
    }, {select:true});
    if(!node) return null;
    // 列表接口只提供摘要；节点创建后再读取完整字段配置，保持工作流设置页为唯一字段来源。
    ensureComfyWorkflow(entry.name).then(data => {
        if(!data || !nodes.includes(node)) return;
        const config = data.config && typeof data.config === 'object' ? data.config : {};
        const fields = Array.isArray(config.fields) ? JSON.parse(JSON.stringify(config.fields)) : [];
        node.workflowFields = fields;
        if(config.title) node.workflowTitle = String(config.title).trim();
        node.workflowReadiness = data.readiness && typeof data.readiness === 'object' ? data.readiness : (node.workflowReadiness || {});
        node.workflowStatus = node.workflowReadiness.can_run === true ? 'ready' : (node.workflowStatus || 'needs_preparation');
        node.title = node.workflowTitle || node.title;
        if(node.comfyAutoSize !== false) node.h = Math.max(Number(node.h) || 0, comfyWorkflowNodeDefaultHeight(fields));
        ensureComfyNodeParamDefaults(node, fields);
        normalizeSmartComfyWorkflowNode(node);
        render();
        scheduleSave();
    }).catch(() => {});
    return node;
}
