            cols:1,
            rows:1,
            width:Math.max(340, Math.round(Number(node.w) || 430)),
            height:Math.max(320, Math.round(Number(node.h) || comfyWorkflowNodeDefaultHeight(node.workflowFields))),
            thumb:96,
