async function loadConfig(){
    try {
        const cfg = await fetch('/api/config', {cache:'no-store'}).then(r => r.json());
        apiProviders = Array.isArray(cfg.api_providers) ? cfg.api_providers : [];
        smartReferenceImageLimits = cfg.reference_image_limits || {default:20,models:{}};
        smartConfigReady = true;
        window.dispatchEvent(new CustomEvent('smart-canvas-config-ready', {detail:{providers:apiProviders}}));
        comfyInstanceCount = Math.max(1, (Array.isArray(cfg.comfy_instances) ? cfg.comfy_instances : []).filter(Boolean).length || 1);
        // 提供商配置已就绪即先渲染参数面板；本地 ComfyUI 工作流按独立节点需要读取。
        sanitizeSmartApiSelection(settings);
        updateProviderModels();
        const workflowRequest = fetch('/api/workflows', {cache:'no-store'})
            .then(r => r.ok ? r.json() : ({workflows:[]})).catch(() => ({workflows:[]}));
        const catalogRequest = fetch('/api/comfy-apps/catalog', {cache:'no-store'})
            .then(r => r.ok ? r.json() : ({entries:[]})).catch(() => ({entries:[]}));
        const wf = await workflowRequest;
        const workflowEntries = Array.isArray(wf.workflows) ? wf.workflows : [];
        // 原始工作流列表通常先返回；立即开放节点切换器，不等待应用库扫描。
        comfyWorkflows = mergeComfyWorkflowCatalog(workflowEntries, []);
        if(nodes.length) render();
        const appCatalog = await catalogRequest;
        comfyWorkflows = mergeComfyWorkflowCatalog(
            workflowEntries,
            Array.isArray(appCatalog.entries) ? appCatalog.entries : (Array.isArray(appCatalog.apps) ? appCatalog.apps : [])
        );
        runningHubWorkflowCache = {};
        lastConfigRefreshAt = Date.now();
        sanitizeSmartApiSelection(settings);
        updateProviderModels();
        // 工作流列表是节点顶部切换器的数据源。配置接口异步返回时，
        // 需要同步重绘已有节点，否则节点会一直只显示创建时的那一个工作流。
        if(nodes.length) render();
        void refreshSavedComfyWorkflowFields();
    } catch(e) {
        toast(tr('smart.toastApiSettingsFail'));
    }
}
