function mergeSmartNode(local, remote){
    const images = mergeSmartImageLists(local.images, remote.images);
    const localDone = smartNodeHasCompletedResult(local);
    const remoteDone = smartNodeHasCompletedResult(remote);
    const localBusy = smartNodeInFlight(local);
    const remoteBusy = smartNodeInFlight(remote);
    if(localDone && remoteBusy && !remoteDone) return completeSmartNodeWithImages(local, images);
    if(remoteDone && localBusy && !localDone) return completeSmartNodeWithImages(remote, images);
    if(localDone && remoteDone){
        const localFinished = Number(local.runFinishedAt || 0);
        const remoteFinished = Number(remote.runFinishedAt || 0);
        return completeSmartNodeWithImages(remoteFinished >= localFinished ? remote : local, images);
    }
    // 本地正在生成/排队的节点完全以本地为准，只把对方可能多出来的图并进来，绝不被对方旧状态冲掉
    if(smartNodeInFlight(local)){
        return {...local, images};
    }
    // 否则以对方（最新保存方）的布局/标题/设置为基底，但图片取并集——双方生成结果都不丢
    const merged = {...remote, images};
    return smartNodeHasDisplayResult(merged) && (merged.pending || merged.queued || smartPendingTasks(merged).length)
        ? completeSmartNodeWithImages(merged, images)
        : merged;
}
function mergeSmartNodeLists(localNodes, remoteNodes){
    const localById = new Map((localNodes || []).map(n => [n.id, n]));
    const remoteById = new Map((remoteNodes || []).map(n => [n.id, n]));
    const order = [];
    const seen = new Set();
    (localNodes || []).forEach(n => { if(!seen.has(n.id)){ seen.add(n.id); order.push(n.id); } });
    (remoteNodes || []).forEach(n => { if(!seen.has(n.id)){ seen.add(n.id); order.push(n.id); } });
    const merged = order.map(id => {
        const local = localById.get(id);
        const remote = remoteById.get(id);
        if(local && !remote) return local;     // 仅本地存在：保留（我新建的节点；对方删了也宁可复活也不丢结果）
        if(remote && !local) return remote;     // 仅对方存在：加入对方新建的节点
        const node = mergeSmartNode(local, remote);
        if(local?.imageLayerTaskIds || remote?.imageLayerTaskIds){
            node.imageLayerHiddenJobIds = [...new Set([...(local.imageLayerHiddenJobIds || []), ...(remote.imageLayerHiddenJobIds || [])])];
            node.imageLayerDeletedNodeKeys = [...new Set([...(local.imageLayerDeletedNodeKeys || []), ...(remote.imageLayerDeletedNodeKeys || [])])];
        }
        return node;
    }).filter(Boolean);
    const hiddenJobs = new Set(merged.flatMap(node => node.imageLayerHiddenJobIds || []));
    const deletedLayers = new Set(merged.flatMap(node => node.imageLayerDeletedNodeKeys || []));
    return merged.filter(node => !node.imageLayerJobId || (
        !hiddenJobs.has(node.imageLayerJobId)
        && !deletedLayers.has(`${node.imageLayerJobId}:${node.imageLayerId}`)
    ));
}
function mergeSmartConnections(localConns, remoteConns, nodeIds, baseConns=null, protectedDeletedKeys=smartConnectionDeletionTombstones){
    const valid = value => Boolean(value?.from && value?.to && nodeIds.has(value.from) && nodeIds.has(value.to));
    const list = value => (Array.isArray(value) ? value : []).filter(valid);
    const local = list(localConns);
    const localKeys = new Set(local.map(connection => smartConnectionIdentity(connection)));
    const protectedDeletes = protectedDeletedKeys instanceof Set ? protectedDeletedKeys : new Set();
    // 已经由当前用户明确断开的边，即使旧客户端稍后把它发回来，也不能被当成“远端新增”。
    // 用户重新拉出同一条边时，addConnection/connectInputNode 会清除对应标记。
    const remote = list(remoteConns).filter(connection => {
        const key = smartConnectionIdentity(connection);
        return !protectedDeletes.has(key) || localKeys.has(key);
    });
    // When no acknowledged snapshot is available (old callers/old pages), keep
    // the previous additive behavior. A loaded canvas always has a snapshot, so
    // normal sync uses the three-way path below.
    if(!Array.isArray(baseConns)) return uniqueSmartConnections([...local, ...remote]);

    const base = list(baseConns);
    const byKey = values => new Map(values.map(connection => [smartConnectionIdentity(connection), connection]));
    const localByKey = byKey(local);
    const remoteByKey = byKey(remote);
    const baseByKey = byKey(base);
    const keys = new Set([...baseByKey.keys(), ...localByKey.keys(), ...remoteByKey.keys()]);
    const out = [];
    keys.forEach(key => {
        const inBase = baseByKey.has(key);
        const inLocal = localByKey.has(key);
        const inRemote = remoteByKey.has(key);
        const localChanged = inLocal !== inBase;
        const remoteChanged = inRemote !== inBase;
        let winner = null;
        if(localChanged && !remoteChanged){
            // Keep an unsaved local add/remove exactly as the user made it.
            winner = localByKey.get(key) || null;
        } else if(!localChanged && remoteChanged){
            // The other editor changed this edge while we did not.
            winner = remoteByKey.get(key) || null;
        } else if(localChanged && remoteChanged){
            // Both sides changed the same edge. A local deletion must not be
            // resurrected by a stale remote copy; when both still exist, keep
            // the local record and its metadata.
            winner = inLocal ? localByKey.get(key) : null;
        } else {
            winner = remoteByKey.get(key) || localByKey.get(key) || null;
        }
        if(winner) out.push(winner);
    });
    return uniqueSmartConnections(out);
}

function acknowledgedSmartConnections(){
    const raw = collabCanvasSnapshot?.connections;
    if(typeof raw !== 'string' || !raw) return null;
    try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : null;
    } catch(_) {
        return null;
    }
}
function applyMergedServerCanvas(serverCanvas){
    if(!serverCanvas || !canvas) return false;
    let cleanedInvalidRecoveries = false;
    const remoteNodes = (Array.isArray(serverCanvas.nodes) ? serverCanvas.nodes : []).map(source => {
        const node = normalizeLegacySmartNode(source);
        if(migrateInvalidImageTaskRecoveries(node)) cleanedInvalidRecoveries = true;
        return node;
    }).filter(Boolean);
    const mergedNodes = mergeSmartNodeLists(nodes, remoteNodes);
    const nodeIds = new Set(mergedNodes.map(n => n.id));
    nodes = preserveSmartBatchPromptRequests(mergedNodes);
    canvas.connections = mergeSmartConnections(
        canvas.connections,
        serverCanvas.connections,
        nodeIds,
        acknowledgedSmartConnections()
    );
    const recoveredLoggedOutputs = recoverStuckOutputsFromLogs();
    const cleanedState = clearCompletedNodeBusyStates();
    canvas.updated_at = Number(serverCanvas.updated_at || canvas.updated_at || 0);
    if(canvas.title !== serverCanvas.title && serverCanvas.title){
        canvas.title = serverCanvas.title;
        const titleEl = document.getElementById('smartTitle');
        if(titleEl) titleEl.textContent = canvas.title;
    }
    // 合并后以刚收到的服务端版本作为下一次增量保存的基线，
    // 避免把对方已保存的节点再次当作本地修改提交。
    collabCaptureSnapshot(serverCanvas, serverCanvas.nodes);
    render();
    if(typeof scheduleConnectionLayerRefresh === 'function') scheduleConnectionLayerRefresh();
    if(cleanedState || recoveredLoggedOutputs || cleanedInvalidRecoveries) scheduleSave();
    if(!sharedCanvasMode){
        resumeSmartPendingTasks();
        resumeJimengPendingNodes();
    }
    return true;
}
async function mergeReloadCanvasNow(){
    if(!canvasId) return;
    if(dragState || selectionState){
        // 用户正在拖拽/框选，稍后再合并，别打断操作
        scheduleCanvasMergeReload(600);
        return;
    }
    try {
        const res = await fetch(`/api/canvases/${encodeURIComponent(canvasId)}`);
        if(!res.ok) return;
        const data = await res.json();
        if(data && data.canvas) applyMergedServerCanvas(data.canvas);
    } catch(e) {}
}
function scheduleCanvasMergeReload(delay=200){
    clearTimeout(canvasSyncTimer);
    canvasSyncTimer = setTimeout(() => { mergeReloadCanvasNow(); }, delay);
}
function handleCanvasUpdatedMessage(data={}){
    if(!data || data.type !== 'canvas_updated') return;
    if(!canvasId || data.canvas_id !== canvasId) return;
    if(data.client_id && data.client_id === smartClientId) return; // 自己发的，忽略
    if(canvasSyncInFlight) return; // 我正在保存，保存完成/409 合并会处理
    const remoteUpdatedAt = Number(data.updated_at || 0);
    if(remoteUpdatedAt && remoteUpdatedAt <= Number(canvas?.updated_at || 0)) return;
    scheduleCanvasMergeReload(200);
}
function startCanvasMetaPoll(){
    // WS / iframe 转发不可靠时的兜底：定期看服务器 updated_at 是否变新，变新就合并拉取
    if(canvasMetaPollTimer) return;
    canvasMetaPollTimer = setInterval(async () => {
        if(!canvasId || !canvas) return;
        if(canvasSyncInFlight || dragState || selectionState) return;
        try {
            const res = await fetch(`/api/canvases/${encodeURIComponent(canvasId)}/meta`);
            if(!res.ok) return;
            const meta = await res.json();
            if(Number(meta.updated_at || 0) > Number(canvas.updated_at || 0)) mergeReloadCanvasNow();
        } catch(e) {}
    }, 8000);
}
function connectAssetLibrarySyncSocket(){
    if(window.parent && window.parent !== window) return;
    const host = window.location.host;
    if(!host) return;
    const protocol = location.protocol === 'https:' ? 'wss' : 'ws';
    const clientId = smartClientId;
    let socket;
    let retryTimer = null;
    const connect = () => {
        try {
            const canvasQuery = canvasId ? `&canvas_id=${encodeURIComponent(canvasId)}` : '';
            socket = new WebSocket(`${protocol}://${host}/ws/stats?client_id=${clientId}${canvasQuery}`);
        } catch(e) {
            retryTimer = setTimeout(connect, 3000);
            return;
        }
        socket.onmessage = event => {
            try {
                const data = JSON.parse(event.data);
                if(data?.type === 'asset_library_updated') handleAssetLibraryUpdatedMessage(data);
                if(data?.type === 'canvas_updated') handleCanvasUpdatedMessage(data);
            } catch(e) {}
        };
        socket.onclose = () => {
            retryTimer = setTimeout(connect, 3000);
        };
        socket.onerror = () => {
            try { socket.close(); } catch(e) {}
        };
    };
    window.addEventListener('beforeunload', () => {
        clearTimeout(retryTimer);
        try { socket?.close(); } catch(e) {}
    });
    connect();
}

function collabSocketIsReady(){
    return Boolean(collabSocket && collabSocket.readyState === WebSocket.OPEN);
}
function collabSend(message){
    if(!collabSocketIsReady() || !message) return false;
    try {
        collabSocket.send(JSON.stringify(message));
        return true;
    } catch(_) { return false; }
}
function collabSelfMember(){
    return collabMembers.get(collabMemberId) || {
        id:collabMemberId,
        name:collabName,
        color:collabColor,
        role:sharedCanvasReadOnly ? 'viewer' : 'editor',
        host:!sharedCanvasMode,
        selected_ids:selectedNodeIds(),
        active_node_id:selectedId || ''
    };
}
function collabRoleText(member){
    if(member?.host) return '主持人';
    return String(member?.role || 'viewer') === 'editor' ? '可编辑' : '仅查看';
}
function collabMemberActivity(member){
    if(!member) return '';
    const locked = [...collabLocks.values()].find(lock => lock?.member?.id === member.id);
    if(locked){
        const node = nodes.find(item => item.id === locked.node_id);
        return `${collabRoleText(member)} · 正在编辑${node ? `「${node.title || '节点'}」` : '节点'}`;
    }
    const activeId = String(member.active_node_id || '');
    if(activeId && (member.selected_ids || []).includes(activeId)){
        const node = nodes.find(item => item.id === activeId);
        return `${collabRoleText(member)} · 已选中${node ? `「${node.title || '节点'}」` : '节点'}`;
    }
    return collabRoleText(member);
}
function renderCollabMembers(){
    if(!canvasCollabStatus || !canvasCollabMemberList) return;
    const members = [...collabMembers.values()].sort((a, b) => {
        if(String(a.id) === String(collabMemberId)) return -1;
        if(String(b.id) === String(collabMemberId)) return 1;
        return String(a.name || '').localeCompare(String(b.name || ''), 'zh-CN');
    });
    canvasCollabStatus.hidden = !collabConnected;
    canvasCollabToggle?.querySelector('[data-collab-count]')?.replaceChildren(document.createTextNode(String(members.length)));
    if(canvasCollabNameInput && document.activeElement !== canvasCollabNameInput) canvasCollabNameInput.value = collabName;
    canvasCollabMemberList.innerHTML = members.length ? members.map(member => {
        const id = String(member.id || '');
        const color = collabSafeColor(member.color, id);
        const isSelf = id === String(collabMemberId);
        const canKick = !isSelf && Boolean(collabSelfMember().host);
        return `<div class="canvas-collab-member-row" style="--member-color:${escapeAttr(color)}" data-member-id="${escapeAttr(id)}">
            <span class="canvas-collab-member-swatch"></span>
            <span class="canvas-collab-member-copy"><strong>${escapeHtml(member.name || '协作者')}${isSelf ? '（你）' : ''}</strong><small>${escapeHtml(collabMemberActivity(member))}</small></span>
            ${canKick ? `<button class="canvas-collab-member-kick" type="button" data-collab-kick="${escapeAttr(id)}">移出</button>` : ''}
        </div>`;
    }).join('') : '<div class="canvas-collab-empty">暂时没有其他在线成员</div>';
}
function renderCollabCursors(){
    if(!canvasCollabCursors) return;
    if(!collabConnected){
        if(canvasCollabCursors.childElementCount) canvasCollabCursors.replaceChildren();
        return;
    }
    const shellRect = shell?.getBoundingClientRect?.();
    if(!shellRect) return;
    const scale = Math.max(0.0001, Number(viewport.scale) || 1);
    const ownId = String(collabMemberId || '');
    const visibleMembers = [...collabMembers.values()]
        .filter(member => String(member.id || '') && String(member.id) !== ownId)
        .filter(member => Number.isFinite(Number(member.x)) && Number.isFinite(Number(member.y)))
        .map(member => {
            const color = collabSafeColor(member.color, member.id);
            const left = Number(viewport.x || 0) + Number(member.x || 0) * scale;
            const top = Number(viewport.y || 0) + Number(member.y || 0) * scale;
            if(left < -80 || top < -80 || left > shellRect.width + 80 || top > shellRect.height + 80) return null;
            return {member, color, left, top};
        }).filter(Boolean);
    const existing = new Map([...canvasCollabCursors.children]
        .map(element => [String(element.dataset.memberId || ''), element])
        .filter(([id]) => id));
    const visibleIds = new Set();
    visibleMembers.forEach(({member, color, left, top}) => {
        const id = String(member.id);
        visibleIds.add(id);
        let element = existing.get(id);
        if(!element){
            element = document.createElement('div');
            element.className = 'canvas-collab-cursor';
            element.dataset.memberId = id;
            element.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3.2 19.7 12l-7.1 1.2-3.1 6.8L4 3.2Z"></path></svg><span class="canvas-collab-cursor-label"></span>';
            canvasCollabCursors.appendChild(element);
        }
        element.style.setProperty('--cursor-color', color);
        element.style.transform = `translate3d(${Math.round(left)}px,${Math.round(top)}px,0)`;
        const label = element.querySelector('.canvas-collab-cursor-label');
        if(label && label.textContent !== String(member.name || '协作者')) label.textContent = String(member.name || '协作者');
    });
    existing.forEach((element, id) => {
        if(!visibleIds.has(id)) element.remove();
    });
}
function collabNodePresenceMarkup(nodeId){
    const entries = [];
    const lock = collabLocks.get(String(nodeId || ''));
    if(lock?.member && String(lock.member.id || '') !== String(collabMemberId || '')){
        const member = lock.member;
        const color = collabSafeColor(member.color, member.id);
        entries.push(`<span class="collab-node-presence-badge locked" style="--member-color:${escapeAttr(color)}">${escapeHtml(member.name || '协作者')}正在编辑</span>`);
    }
    [...collabMembers.values()].forEach(member => {
        if(String(member.id || '') === String(collabMemberId || '')) return;
        if(!(member.selected_ids || []).map(String).includes(String(nodeId || ''))) return;
        if(lock?.member?.id === member.id) return;
        const color = collabSafeColor(member.color, member.id);
        entries.push(`<span class="collab-node-presence-badge" style="--member-color:${escapeAttr(color)}">${escapeHtml(member.name || '协作者')}已选中</span>`);
    });
    return entries.length ? `<div class="collab-node-presence">${entries.join('')}</div>` : '';
}
function renderCollabPresence(){
    renderCollabMembers();
    renderCollabCursors();
}
function collabHandleSnapshot(data){
    collabMemberId = String(data.self_id || collabMemberId || smartClientId);
    collabMembers = new Map((Array.isArray(data.members) ? data.members : []).map(member => [String(member.id || ''), member]).filter(([id]) => id));
    collabLocks = new Map((Array.isArray(data.locks) ? data.locks : []).map(lock => [String(lock.node_id || ''), lock]).filter(([id]) => id));
    renderCollabPresence();
    render();
}
function handleCollabMessage(data){
    if(!data || typeof data !== 'object') return;
    const type = String(data.type || '');
    if(type === 'collab_snapshot'){ collabHandleSnapshot(data); return; }
    if(type === 'collab_join' || type === 'collab_presence'){
        const member = data.member;
        if(member?.id) collabMembers.set(String(member.id), member);
        renderCollabPresence();
        render();
        return;
    }
    if(type === 'collab_leave'){
        collabMembers.delete(String(data.member_id || ''));
        (data.released_node_ids || []).forEach(id => collabLocks.delete(String(id)));
        renderCollabPresence();
        render();
        return;
    }
    if(type === 'collab_cursor'){
        const member = collabMembers.get(String(data.member_id || ''));
        if(member){ member.x = Number(data.x || 0); member.y = Number(data.y || 0); renderCollabCursors(); }
        return;
    }
    if(type === 'collab_selection'){
        const member = collabMembers.get(String(data.member_id || ''));
        if(member){ member.selected_ids = Array.isArray(data.node_ids) ? data.node_ids : []; member.active_node_id = String(data.active_node_id || ''); }
        renderCollabMembers();
        render();
        return;
    }
    if(type === 'collab_lock_changed'){
        const nodeId = String(data.node_id || '');
        if(!nodeId) return;
        if(data.member) collabLocks.set(nodeId, data);
        else collabLocks.delete(nodeId);
        renderCollabMembers();
        render();
        return;
    }
    if(type === 'collab_lock' && data.ok === false){
        collabLocks.delete(String(data.node_id || ''));
        const who = data.member?.name || '其他成员';
        toast(`${who}正在编辑此节点`);
        renderCollabPresence();
        render();
        return;
    }
    if(type === 'collab_canvas_changed'){
        if(data.client_id && String(data.client_id) === String(smartClientId)) return;
        handleCanvasUpdatedMessage({type:'canvas_updated', canvas_id:canvasId, updated_at:data.updated_at || 0, client_id:data.client_id || ''});
        return;
    }
    if(type === 'collab_kicked'){
        toast('你已被主持人移出画布');
        sharedCanvasReadOnly = true;
        document.body.classList.add('canvas-share-readonly');
        try { collabSocket?.close(); } catch(_) {}
    }
}
function collabCanEditNode(nodeId, silent=false){
    if(sharedCanvasReadOnly){ if(!silent) toast('当前分享链接为只读，不能修改画布'); return false; }
    const lock = collabLocks.get(String(nodeId || ''));
    if(lock?.member && String(lock.member.id || '') !== String(collabMemberId || '')){
        if(!silent) toast(`${lock.member.name || '其他成员'}正在编辑此节点`);
        return false;
    }
    return true;
}
function collabAcquireNodeLock(nodeId){
    const id = String(nodeId || '');
    if(!id || !collabCanEditNode(id)) return false;
    const existing = collabLocks.get(id);
    if(existing?.member?.id && String(existing.member.id) !== String(collabMemberId)) return false;
    const member = collabSelfMember();
    collabLocks.set(id, {node_id:id, member:{...member, id:collabMemberId, name:collabName, color:collabColor}, expires_at:Date.now() + 16000});
    collabSend({type:'lock', action:'acquire', node_id:id});
    renderCollabPresence();
    return true;
}
function collabAcquireNodeLocks(ids=[]){
    const wanted = [...new Set((ids || []).map(String).filter(Boolean))];
    if(!wanted.every(id => collabCanEditNode(id))) return false;
    wanted.forEach(id => collabAcquireNodeLock(id));
    return true;
}
function collabReleaseLocks(ids=[]){
    const wanted = [...new Set((ids || []).map(String).filter(Boolean))];
    wanted.forEach(id => {
        const lock = collabLocks.get(id);
        if(lock?.member?.id && String(lock.member.id) !== String(collabMemberId)) return;
        collabLocks.delete(id);
        collabSend({type:'lock', action:'release', node_id:id});
    });
    renderCollabPresence();
}
function broadcastCollabSelection(){
    if(!collabSocketIsReady()) return;
    const nodeIds = selectedNodeIds().slice(0, 24);
    const signature = `${nodeIds.join(',')}|${selectedId || ''}`;
    if(signature === collabLastSelectionSignature) return;
    collabLastSelectionSignature = signature;
    collabSend({type:'selection', node_ids:nodeIds, active_node_id:selectedId || ''});
}
function broadcastCollabCursor(event){
    if(!collabSocketIsReady() || !event || !Number.isFinite(event.clientX) || !Number.isFinite(event.clientY)) return;
    const now = performance.now();
    if(now - collabLastCursorSentAt < 36) return;
    const point = clientToWorldPoint(event.clientX, event.clientY);
    if(!point || !Number.isFinite(point.x) || !Number.isFinite(point.y)) return;
    collabLastCursorSentAt = now;
    collabSend({type:'cursor', x:point.x, y:point.y});
}
function initCollabUi(){
    if(canvasCollabToggle && canvasCollabStatus) {
        canvasCollabToggle?.addEventListener('click', () => {
            const open = canvasCollabPanel?.hidden !== false;
            if(canvasCollabPanel) canvasCollabPanel.hidden = !open;
            canvasCollabToggle?.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
        canvasCollabPanelClose?.addEventListener('click', () => {
            if(canvasCollabPanel) canvasCollabPanel.hidden = true;
            canvasCollabToggle?.setAttribute('aria-expanded', 'false');
        });
        canvasCollabNameInput?.addEventListener('change', () => {
            collabName = String(canvasCollabNameInput.value || '').replace(/[\x00-\x1f\x7f]/g, '').trim().slice(0, 32) || '我';
            canvasCollabNameInput.value = collabName;
            collabSaveValue(COLLAB_NAME_KEY, collabName);
            collabSend({type:'rename', name:collabName});
        });
        canvasCollabMemberList?.addEventListener('click', event => {
            const button = event.target.closest('[data-collab-kick]');
            if(!button) return;
            const memberId = button.dataset.collabKick || '';
            if(memberId && window.confirm(`确定将 ${button.closest('[data-member-id]')?.querySelector('strong')?.textContent || '该成员'} 移出画布吗？`)){
                collabSend({type:'kick', member_id:memberId});
            }
        });
        if(canvasCollabNameInput) canvasCollabNameInput.value = collabName;
    }
}
function connectCanvasCollaborationSocket(){
    if(!canvasId || typeof WebSocket === 'undefined' || collabUnloading) return;
    clearTimeout(collabRetryTimer);
    const protocol = location.protocol === 'https:' ? 'wss' : 'ws';
    const query = new URLSearchParams({client_id:smartClientId, name:collabName, color:collabColor});
    // 页面是直接复制的完整分享地址时，先把 bearer 凭证带进协作握手；
    // 服务端仍会立即换成 HttpOnly Cookie，后续消息不再携带它。
    if(sharedCanvasMode && shareQueryId && shareQueryToken){
        query.set('share_id', shareQueryId);
        query.set('token', shareQueryToken);
    }
    let socket;
    try { socket = new WebSocket(`${protocol}://${location.host}/ws/canvas-collab/${encodeURIComponent(canvasId)}?${query.toString()}`); }
    catch(_) { collabRetryTimer = setTimeout(connectCanvasCollaborationSocket, 3000); return; }
    collabSocket = socket;
    socket.onopen = () => {
        if(collabSocket !== socket) return;
        collabConnected = true;
        canvasCollabStatus && (canvasCollabStatus.hidden = false);
        collabSend({type:'hello', name:collabName});
        collabLastSelectionSignature = '';
        broadcastCollabSelection();
        [...collabLocks.entries()].filter(([,lock]) => String(lock?.member?.id || '') === String(collabMemberId)).forEach(([nodeId]) => {
            collabSend({type:'lock', action:'acquire', node_id:nodeId});
        });
        clearInterval(collabHeartbeatTimer);
        collabHeartbeatTimer = setInterval(() => {
            collabSend({type:'heartbeat', locks:[...collabLocks.entries()].filter(([,lock]) => String(lock?.member?.id || '') === String(collabMemberId)).map(([id]) => id)});
        }, 5000);
        renderCollabPresence();
    };
    socket.onmessage = event => {
        try { handleCollabMessage(JSON.parse(event.data)); } catch(_) {}
    };
    socket.onerror = () => { try { socket.close(); } catch(_) {} };
    socket.onclose = () => {
        if(collabSocket !== socket) return;
        collabConnected = false;
        collabSocket = null;
        clearInterval(collabHeartbeatTimer);
        collabMembers.clear();
        collabLocks.clear();
        renderCollabPresence();
        if(!collabUnloading) collabRetryTimer = setTimeout(connectCanvasCollaborationSocket, 3000);
    };
}
function collabJsonSignature(value){
    try { return JSON.stringify(value ?? null); } catch(_) { return ''; }
}
function collabNodeSignature(node){
    if(!node || typeof node !== 'object') return collabJsonSignature(node);
    const comparable = {...node};
    delete comparable._collab_updated_at;
    return collabJsonSignature(comparable);
}
function collabCaptureSnapshot(sourceCanvas=canvas, sourceNodes=nodes){
    if(!sourceCanvas) return;
    const list = Array.isArray(sourceNodes) ? sourceNodes : (Array.isArray(sourceCanvas.nodes) ? sourceCanvas.nodes : []);
    collabNodeSnapshot = new Map(list.filter(node => node?.id).map(node => [String(node.id), {
        signature:collabNodeSignature(node),
        revision:Number(node._collab_updated_at || sourceCanvas.updated_at || 0)
    }]));
    collabCanvasSnapshot = {
        title:String(sourceCanvas.title || ''),
        icon:String(sourceCanvas.icon || ''),
        connections:collabJsonSignature(sourceCanvas.connections || []),
        viewport:collabJsonSignature(sourceCanvas.viewport || {}),
        logs:collabJsonSignature(sourceCanvas.logs || []),
        settings:collabJsonSignature(sourceCanvas.settings || {})
    };
}
function collabApplyReturnedRevisions(serverCanvas){
    if(!serverCanvas || !Array.isArray(serverCanvas.nodes)) return;
    const revisions = new Map(serverCanvas.nodes.filter(node => node?.id).map(node => [String(node.id), Number(node._collab_updated_at || serverCanvas.updated_at || 0)]));
    nodes.forEach(node => {
        if(revisions.has(String(node.id))) node._collab_updated_at = revisions.get(String(node.id));
    });
}
function collabNodeDiff(storageNodes){
    const current = new Map((storageNodes || []).filter(node => node?.id).map(node => [String(node.id), node]));
    const changes = [];
    current.forEach((node, id) => {
        const previous = collabNodeSnapshot.get(id);
        const signature = collabNodeSignature(node);
        if(!previous || previous.signature !== signature){
            changes.push({id, node, base_updated_at:Number(previous?.revision || canvas?.updated_at || 0)});
        }
    });
    const deleted_ids = [...collabNodeSnapshot.keys()].filter(id => !current.has(id));
    return {changes, deleted_ids};
}
function collabReplaceWithServerCanvas(serverCanvas){
    if(!serverCanvas || !canvas) return;
    stopReplacedCanvasDependencies();
    canvas = {...canvas, ...serverCanvas};
    const serverConnections = Array.isArray(serverCanvas.connections) ? serverCanvas.connections : [];
    canvas.logs = Array.isArray(serverCanvas.logs) ? serverCanvas.logs : [];
    canvas.settings = serverCanvas.settings && typeof serverCanvas.settings === 'object' ? serverCanvas.settings : {};
    nodes = preserveSmartBatchPromptRequests((Array.isArray(serverCanvas.nodes) ? serverCanvas.nodes : []).map(normalizeLegacySmartNode).filter(Boolean));
    nodes.forEach(node => { normalizeSmartCameraNode(node); normalizeSmartCompareNode(node); });
    canvas.connections = mergeSmartConnections(
        [],
        serverConnections,
        new Set(nodes.map(node => node.id)),
        [],
        smartConnectionDeletionTombstones
    );
    viewport = {...viewport, ...(serverCanvas.viewport || {})};
    viewport.scale = safeScale(viewport.scale);
    document.getElementById('smartTitle')?.replaceChildren(document.createTextNode(canvas.title || tr('canvas.smartCanvas')));
    applyViewport();
    collabCaptureSnapshot(canvas, nodes);
    const restoredLegacyAgentTextStacks = restoreLegacyAgentTextStacks();
    const interruptedTextRuns = !sharedCanvasMode && nodes.reduce((changed, node) => recoverInterruptedSmartTextRun(node) || changed, false);
    render();
    if(!sharedCanvasMode){
        resumeSmartPendingTasks();
        resumeJimengPendingNodes();
    }
    if((restoredLegacyAgentTextStacks || interruptedTextRuns) && !sharedCanvasReadOnly) scheduleSave();
}
function collabConflictSummary(node){
    if(!node) return '（节点已删除）';
    const fields = ['title','type','x','y','w','h','text','userPrompt','outputText'];
    const summary = {};
    fields.forEach(key => { if(node[key] !== undefined) summary[key] = node[key]; });
    const text = collabJsonSignature(summary);
    return text.length > 300 ? `${text.slice(0, 300)}…` : text;
}
function closeCollabConflictDialog(){
    document.querySelector('.canvas-collab-conflict-backdrop')?.remove();
    collabConflictState = null;
}
function resolveCollabConflict(choice){
    const state = collabConflictState;
    if(!state?.serverCanvas) return closeCollabConflictDialog();
    if(choice === 'remote'){
        clearAllSmartConnectionDeletionTombstones();
        collabReplaceWithServerCanvas(state.serverCanvas);
        closeCollabConflictDialog();
        return;
    }
    if(choice === 'mine'){
        const localChanges = state.localChanges || [];
        const localDeleted = new Set(state.localDeletedIds || []);
        collabReplaceWithServerCanvas(state.serverCanvas);
        // collabReplaceWithServerCanvas 会先按删除标记挡住旧边；这里仍以服务器原始连线
        // 作为保存基线，下一次保存才能把“我的断线”真正写回服务器。
        collabCanvasSnapshot.connections = collabJsonSignature(state.serverCanvas.connections || []);
        const byId = new Map(nodes.map(node => [String(node.id), node]));
        localChanges.forEach(change => {
            const source = change.node || change;
            if(!source?.id) return;
            const copy = JSON.parse(JSON.stringify(source));
            copy._collab_updated_at = Number(state.serverCanvas.updated_at || 0);
            byId.set(String(source.id), copy);
        });
        localDeleted.forEach(id => byId.delete(String(id)));
        nodes = preserveSmartBatchPromptRequests([...byId.values()]);
        if(!sharedCanvasMode) nodes.forEach(recoverInterruptedSmartTextRun);
        canvas.nodes = nodes;
        closeCollabConflictDialog();
        render();
        scheduleSave();
        return;
    }
    // “合并其余修改”沿用原有图片/节点合并策略，适合只想保留双方新增内容。
    applyMergedServerCanvas(state.serverCanvas);
    closeCollabConflictDialog();
    scheduleSave();
}
function openCollabConflictDialog(serverCanvas, conflicts, localChanges, localDeletedIds){
    document.querySelector('.canvas-collab-conflict-backdrop')?.remove();
    collabConflictState = {serverCanvas, conflicts, localChanges, localDeletedIds};
    const rows = (conflicts || []).map(conflict => {
        const title = conflict.local?.title || conflict.remote?.title || '未命名节点';
        return `<article class="canvas-collab-conflict-row"><strong>${escapeHtml(title)}</strong><div class="canvas-collab-conflict-columns"><div><small>我的版本</small><code>${escapeHtml(collabConflictSummary(conflict.local))}</code></div><div><small>对方版本</small><code>${escapeHtml(collabConflictSummary(conflict.remote))}</code></div></div></article>`;
    }).join('');
    const backdrop = document.createElement('div');
    backdrop.className = 'canvas-collab-conflict-backdrop';
    backdrop.innerHTML = `<section class="canvas-collab-conflict-dialog" role="dialog" aria-modal="true" aria-label="协作冲突">
        <header><div><small>协作冲突</small><h2>同一节点有两个版本</h2></div><button type="button" data-collab-conflict-close aria-label="关闭">×</button></header>
        <p class="canvas-collab-conflict-intro">选择如何处理下面的冲突。未冲突的节点会继续保留。</p>
        <div class="canvas-collab-conflict-list">${rows || '<p>检测到画布版本冲突。</p>'}</div>
        <footer><button type="button" data-collab-conflict-action="remote">采用对方版本</button><button type="button" data-collab-conflict-action="merge">合并其余修改</button><button type="button" class="primary" data-collab-conflict-action="mine">保留我的版本</button></footer>
    </section>`;
    document.body.appendChild(backdrop);
    backdrop.addEventListener('click', event => {
        if(event.target === backdrop || event.target.closest('[data-collab-conflict-close]')) closeCollabConflictDialog();
        const action = event.target.closest('[data-collab-conflict-action]')?.dataset.collabConflictAction;
        if(action) resolveCollabConflict(action);
    });
}
function setAssetLibraryFromResponse(data, options={}){
    assetLibrary = data.library || assetLibrary;
    assetLibraryUpdatedAt = Number(assetLibrary.updated_at || assetLibraryUpdatedAt || 0);
    const libs = assetLibraries();
    if(!libs.some(library => library.id === activeAssetLibraryId)){
        activeAssetLibraryId = libs.find(library => library.id === assetLibrary.active_library_id)?.id || libs[0]?.id || '';
    }
    if(options.render !== false) promptMentionMenu.refreshAssets();
    if(smartWorkflowTransfer.isOpen()) renderSmartWorkflowLibrary();
}
function toggleAssetLibrary(open=!assetLibraryOpen){
    if(!assetPanel || !assetToggle) return;
    const nextOpen = !!open;
    closeSmartCanvasFeaturePanels(nextOpen ? 'asset' : '');
    assetLibraryOpen = nextOpen;
    assetPanel.classList.toggle('open', assetLibraryOpen);
    assetToggle?.classList.toggle('active', assetLibraryOpen);
    if(assetLibraryOpen){
        localAssetSidebar.render('__root__');
        loadAssetLibrary();
    }
    render();
}
function assetMediaKind(item){
    return XiaomeiShellKernel.mediaKind(item);
}
function assetNodeImageFromItem(item, fallbackName='asset'){
    const image = {
        url:item?.url || '',
        name:item?.name || fallbackName,
        kind:item?.kind || assetMediaKind(item)
    };
    const assetRefId = String(item?.asset_ref_id || item?.asset_id || (String(item?.id || '').startsWith('asset_') ? item.id : '') || '');
    if(assetRefId) image.asset_ref_id = assetRefId;
    copyMediaSizeFields(item, image);
    if(item?.asset_uris && typeof item.asset_uris === 'object') image.asset_uris = {...item.asset_uris};
    return image;
}
