function preserveSmartBatchPromptRequests(nextNodes){
    const currentById = new Map(nodes.map(node => [node.id, node]));
    return nextNodes.map(next => {
        if(next.type !== 'smart-loop') return next;
        const current = currentById.get(next.id);
        // 请求闭包和 WeakMap 都持有原对象；撤销、协作合并时必须保留其身份。
        if(current?.type === 'smart-loop' && smartBatchPromptProgress.has(current)){
            if(current !== next){
                Object.keys(current).forEach(key => { if(!Object.prototype.hasOwnProperty.call(next, key)) delete current[key]; });
                Object.assign(current, next);
            }
            current.aiSplitRunning = true;
            return current;
        }
        next.aiSplitRunning = false;
        return next;
    });
}
function smartBatchPromptProgressHtml(node){
    const progress = smartBatchPromptProgress.get(node);
    const elapsed = progress ? Math.max(0, nowMs() - progress.startedAt) : 0;
    return `<div class="batch-prompt-progress" data-batch-prompt-status data-batch-prompt-progress="${escapeAttr(node.id)}">
        <span class="batch-head-icon" aria-hidden="true"><span class="batch-prompt-spinner"></span></span>
        <div class="batch-prompt-progress-copy">
            <strong>${escapeHtml(progress?.label || '正在生成分屏提示词')}</strong>
            <div class="batch-prompt-progress-meta">
                <span data-batch-prompt-phase role="status">${escapeHtml(progress?.phase || '等待文本模型返回')}</span>
                <span data-batch-prompt-elapsed>已用 ${formatRunDuration(elapsed)}</span>
            </div>
        </div>
        <button class="batch-prompt-cancel" type="button" data-batch-prompt-cancel="${escapeAttr(node.id)}" title="取消本次提示词处理">取消</button>
    </div>`;
}
function refreshSmartBatchPromptProgress(nodeMap){
    world.querySelectorAll('[data-batch-prompt-progress]').forEach(el => {
        const node = nodeMap.get(el.dataset.batchPromptProgress);
        const progress = node && smartBatchPromptProgress.get(node);
        if(!node?.aiSplitRunning || !progress) return;
        const phase = el.querySelector('[data-batch-prompt-phase]');
        if(phase.textContent !== progress.phase) phase.textContent = progress.phase;
        const elapsed = el.querySelector('[data-batch-prompt-elapsed]');
        const elapsedText = `已用 ${formatRunDuration(Math.max(0, nowMs() - progress.startedAt))}`;
        if(elapsed.textContent !== elapsedText) elapsed.textContent = elapsedText;
    });
}
function smartBatchPromptCancelled(node){
    return Boolean(smartBatchPromptProgress.get(node)?.cancelled);
}
function cancelSmartBatchPromptRun(node){
    const progress = smartBatchPromptProgress.get(node);
    if(!node?.aiSplitRunning || !progress?.controller || progress.cancelled) return;
    progress.cancelled = true;
    progress.controller.abort();
}
function smartBatchScreenInFlight(loop, paint){
    const run = smartCascadeRunForLoop(loop.id);
    return Boolean(paint && (smartNodeInFlight(paint) || run?.screenRuns?.has(paint.id)
        || (run?.batchRunning && !run.stopRequested && run.runPath?.states?.[`${loop.id}->${paint.id}`] === 'wait')));
}
function smartBatchCancellableTasks(paint){
    return smartPendingTasks(paint).filter(task => !task.failed && /^(canvas_img_|canvas_comfy_)/.test(task.taskId));
}
function smartBatchScreenHasCancellableTask(paint){
    return Boolean(paint.jimengPending || smartBatchCancellableTasks(paint).length);
}
function smartBatchOutputSizeLabel(settings){
    return settings.resolution === 'custom' ? `${settings.customWidth} × ${settings.customHeight} px`
        : `${settings.ratio === 'custom' ? settings.customRatio : smartBatchRatioLabel(settings.ratio)} · ${String(settings.resolution || '1k').toUpperCase()}`;
}
function validateSmartBatchSizeInputs(nodeId){
    const input = world.querySelector(`.image-node[data-id="${CSS.escape(nodeId)}"] [data-loop-batch-image-param][type="number"]:invalid`);
    return !input || input.reportValidity();
}
function markSmartBatchScreenCancelled(paint){
    markSmartNodeComplete(paint);
    paint.batchGenerationCancelled = true;
}
async function runSmartBatchScreen(loop, index){
    if(!collabCanMutateCanvas() || loop.aiSplitRunning || smartBatchStopRequests.has(loop.id)) return;
    if(!validateSmartBatchSizeInputs(loop.id)) return;
    let runState = smartCascadeRunForLoop(loop.id);
    if(runState && (!runState.screenRuns || runState.stopRequested)) return;
    if(smartLoopAiSplitIsStale(loop)){ toast(smartBatchPurposeChanged(loop) ? '生成类型或平台已改变，请重新生成分屏提示词' : '输入文案已改变，请重新拆分或生成提示词'); return; }
    if(!String(loop.aiSplitPrompts?.[index]?.prompt ?? smartLoopPromptFieldValues(loop)[index] ?? '').trim()){ toast('请先填写当前屏提示词'); return; }
    ensureSmartLoopDetailPaintNodes(loop, smartLoopPairedPromptValues(loop).length);
    const paint = smartLoopDetailPaintNodes(loop).find(item => Number(item.batchDetailScreenIndex) === index + 1);
    if(!paint || !smartLoopPreviewImages(loop).length) { toast('请先添加产品图和当前屏提示词'); return; }
    if(smartBatchScreenInFlight(loop, paint)) return;
    runState ||= {runKey:loop.id, loopId:loop.id, stopRequested:false, runPath:{states:{}}, screenRuns:new Set()};
    runState.screenRuns.add(paint.id);
    smartCascadeRuns.set(loop.id, runState);
    syncSmartCascadeLegacyState(loop.id);
    try {
        pushUndo();
        applySmartLoopBatchImageSettings(loop, [paint]);
        await runLoopRoundIntoSlot(loop, paint, paint, {index:index + 1, total:smartLoopCount(loop), nodeId:loop.id, batchConcurrency:smartLoopPairedPromptValues(loop).length, forceWorkflow:true, runState, roundOutputs:new Map()});
    } catch(error){
        if(!error?.smartCascadeStopped) toast(error.message || '当前屏生成失败，请重试');
    }
    finally {
        runState.screenRuns.delete(paint.id);
        if(!runState.batchRunning && !runState.screenRuns.size && smartCascadeRuns.get(loop.id) === runState) smartCascadeRuns.delete(loop.id);
        syncSmartCascadeLegacyState(); scheduleSave(); render();
    }
}
