function refreshGenerationProgressRing(node, ring, task=null){
    if(!node || !ring) return;
    const compact = Boolean(ring.closest('.generation-progress-wrap')?.classList.contains('compact'));
    const display = generationTaskDisplay(node, task, compact);
    const title = display.source === 'real' ? (node?.runSettings?.engine === 'comfy' ? '本地 ComfyUI 实时进度' : '上游实时进度') : display.source === 'indeterminate' && node?.runSettings?.engine === 'comfy' ? '已等待时间（本地 ComfyUI 尚未提供百分比）' : display.source === 'indeterminate' ? '已等待时间（上游未提供百分比）' : '预计进度（上游未提供百分比）';
    ring.style.setProperty('--generation-progress', display.percent);
    ring.dataset.progressPhase = display.phase;
    ring.dataset.progressSource = display.source;
    ring.dataset.progressValue = display.percent;
    ['queued', 'submitting', 'running', 'waiting', 'real', 'estimated', 'indeterminate'].forEach(state => {
        ring.classList.toggle(`is-${state}`, display.phase === state || display.source === state);
    });
    const value = ring.querySelector('span');
    if(value && value.textContent !== display.value) value.textContent = display.value;
    const wrap = ring.closest('.generation-progress-wrap');
    if(wrap){
        wrap.title = title;
        const label = wrap.querySelector('.generation-progress-label');
        if(label && label.textContent !== display.label) label.textContent = display.label;
    }
}
let smartProgressRenderPending = false;
function refreshRunningNodeProgress(){
    // 进度轮询只改任务字段（进度/状态/队列信息），全部显示在这些进度环和
    // 计时标签里。逐个刷新即可；此前这里走整棵 render()，每 1~2 秒重建
    // 全部节点 DOM 并重绑事件，生成期间拖动/缩放画布会反复整帧冻结。
    nodes.forEach(node => {
        if(!node || node.id === SMART_LOG_PREVIEW_NODE_ID) return;
        const tasks = smartPendingTasks(node);
        const busy = tasks.length
            || node.pending
            || node.running
            || node.jimengPending
            || node.queued
            || smartComfyTaskProgressByNode.has(node.id);
        if(!busy) return;
        const nodeEl = world.querySelector(`.image-node[data-id="${CSS.escape(node.id)}"]`);
        if(!nodeEl) return;
        nodeEl.querySelectorAll('.generation-progress-ring[data-generation-progress="1"]').forEach((ring, index) => {
            if(ring.closest('.loop-batch-overview')) return;
            const taskId = ring.dataset.generationTaskId || '';
            const task = (taskId && tasks.find(item => item.taskId === taskId))
                || tasks[index]
                || smartComfyTaskProgressByNode.get(node.id)
                || null;
            refreshGenerationProgressRing(node, ring, task);
        });
    });
    refreshRunTimerPills();
}
function requestSmartProgressRender(){
    if(smartProgressRenderPending) return;
    smartProgressRenderPending = true;
    requestAnimationFrame(() => {
        smartProgressRenderPending = false;
        refreshRunningNodeProgress();
    });
}
