        // 第二阶段：重叠的卡片弹开成扇形牌堆。
        const stackElement = world.querySelector(`.image-node[data-id="${CSS.escape(collapsedId)}"] .collapsed-stack`);
        smartFoldPlayFanAnimation(stackElement, smartFoldImageRatiosForNodes(selected, layout.stackHeight));
