function normalizeComfyNodeFieldValue(field, value){
    if(field?.type === 'boolean') return Boolean(value);
    if(field?.type === 'number' || field?.type === 'slider'){
        if(value === '') return '';
        const number = Number(value);
        return Number.isFinite(number) ? number : (field.default ?? '');
    }
    return value ?? '';
}
function setComfyNodeFieldValue(node, fieldId, value){
    if(!isSmartComfyWorkflowNode(node) || !fieldId) return;
    const fields = node.workflowFields || [];
    const field = fields.find(item => String(item?.id || '') === String(fieldId))
        || fields.filter(item => item?.preset_links)
            .flatMap(item => comfyPresetControlFields(node, item))
            .find(item => item.id === fieldId);
    if(!field) return;
    const next = smartSettingsForNode(node);
    next.engine = 'comfy';
    next.comfyMode = 'custom';
    next.comfyWorkflow = node.workflowRef;
    next.comfyWorkflowTitle = node.workflowTitle;
    next.comfyWorkflowFields = JSON.parse(JSON.stringify(node.workflowFields || []));
    next.comfyParams = {...(next.comfyParams || {}), [field.id]:normalizeComfyNodeFieldValue(field, value)};
    node.runSettings = settingsForStorage(next);
    ensureComfyNodeParamDefaults(node, node.workflowFields);
    const subject = activeSettingsSubject();
    if(subject?.id === node.id){
        settings = cloneSmartSettings(node.runSettings);
        renderDynamicParams();
    }
    scheduleSave();
}
async function switchComfyWorkflowForNode(node, workflowName){
    if(!isSmartComfyWorkflowNode(node) || !workflowName) return;
    if(!collabCanEditNode(node.id)) return;
    if(workflowName === node.workflowRef){
        comfyWorkflowChanges.delete(node.id);
        return;
    }
    const previousName = node.workflowRef;
    const change = beginComfyWorkflowChange(node.id);
    const owner = () => {
        if(!currentComfyWorkflowChange(change)) return null;
        const current = nodes.find(item => item.id === change.nodeId);
        return isSmartComfyWorkflowNode(current) && current.workflowRef === previousName && collabCanEditNode(current.id, true)
            ? current : null;
    };
    try {
        const data = await ensureComfyWorkflow(workflowName);
        node = owner();
        if(!node) return;
        if(!data) throw new Error('工作流不存在或尚未准备完成');
        const config = data.config && typeof data.config === 'object' ? data.config : {};
        const fields = Array.isArray(config.fields) ? JSON.parse(JSON.stringify(config.fields)) : [];
        const entry = (comfyWorkflows || []).find(item => item?.name === workflowName) || {};
        const title = String(config.title || entry.title || workflowName.replace(/\.json$/i, '') || 'ComfyUI 工作流').trim();
        const readiness = data.readiness && typeof data.readiness === 'object' ? data.readiness : (entry.readiness || {});
        pushUndo();
        node.workflowRef = workflowName;
        node.workflowTitle = title;
        node.title = title;
        node.workflowFields = fields;
        node.workflowReadiness = readiness;
        node.workflowStatus = readiness.can_run === true ? 'ready' : 'needs_preparation';
        const next = smartSettingsForNode(node);
        next.engine = 'comfy';
        next.comfyMode = 'custom';
        next.comfyWorkflow = workflowName;
        next.comfyWorkflowTitle = title;
        next.comfyWorkflowFields = fields;
        next.comfyParams = {};
        node.runSettings = settingsForStorage(next);
        ensureComfyNodeParamDefaults(node, fields);
        const subject = activeSettingsSubject();
        if(subject?.id === node.id) settings = cloneSmartSettings(node.runSettings);
        document.activeElement?.blur?.();
        renderDynamicParams();
        render();
        scheduleSave();
        toast(`已切换到「${title}」`);
    } catch(error){
        node = owner();
        if(!node) return;
        const select = world.querySelector(`.image-node[data-id="${CSS.escape(node.id)}"] [data-comfy-node-workflow]`);
        if(select) select.value = previousName;
        toast((error?.message || '工作流切换失败').slice(0, 160));
    } finally {
        finishComfyWorkflowChange(change);
    }
}
function bindComfyWorkflowNodeControls(el, node){
    if(!isSmartComfyWorkflowNode(node)) return;
    if(el.dataset.comfyWheelGuard !== '1'){
        el.dataset.comfyWheelGuard = '1';
        el.addEventListener('wheel', event => event.stopPropagation(), {passive:true, capture:true});
    }
    const controls = el.querySelectorAll('[data-comfy-node-param],[data-comfy-node-bool],[data-comfy-node-random],[data-comfy-node-workflow],[data-comfy-node-run]');
    let undoStarted = false;
    const startUndo = () => {
        if(undoStarted) return;
        capturePendingUndo();
        undoStarted = true;
    };
    const finishUndo = () => {
        if(!undoStarted) return;
        commitPendingUndo();
        undoStarted = false;
    };
    controls.forEach(control => {
        control.addEventListener('mousedown', event => event.stopPropagation());
        control.addEventListener('click', event => event.stopPropagation());
        control.addEventListener('dblclick', event => event.stopPropagation());
        if(control.matches('[data-comfy-node-workflow]')) return;
        control.addEventListener('focus', startUndo, true);
        control.addEventListener('blur', () => setTimeout(finishUndo, 0), true);
    });
    const workflowSelect = el.querySelector('[data-comfy-node-workflow]');
    const run = el.querySelector('[data-comfy-node-run]');
    if(run) run.onclick = async event => {
        event.preventDefault();
        event.stopPropagation();
        if(smartNodeInFlight(node) || comfyNodeSubmissions.has(node.id) || !collabCanMutateCanvas(true) || !collabCanEditNode(node.id, true)) return;
        selectedId = node.id;
        selectedIds = [];
        selectedImage = {nodeId:'', index:-1};
        settings = cloneSmartSettings(smartSettingsForNode(node));
        lastComposerNodeId = '';
        updateComposer();
        comfyNodeSubmissions.add(node.id);
        run.disabled = true;
        try { await runGeneration(); }
        finally { comfyNodeSubmissions.delete(node.id); syncRunButtonState(); render(); }
    };
    if(workflowSelect) workflowSelect.onclick = event => {
        event.preventDefault();
        event.stopPropagation();
        if(!collabCanEditNode(node.id)) return;
        openComfyNodeWorkflowPicker(node, workflowSelect, workflowName => void switchComfyWorkflowForNode(node, workflowName));
    };
    el.querySelectorAll('[data-comfy-node-param]').forEach(input => {
        const update = event => {
            event.stopPropagation();
            startUndo();
            const fieldId = input.dataset.comfyNodeParam;
            setComfyNodeFieldValue(node, fieldId, input.value);
            if(input.tagName === 'SELECT' && (node.workflowFields || []).some(field => field.id === fieldId && field.preset_links)){
                finishUndo();
                render();
            }
        };
        if(input.tagName !== 'SELECT') input.oninput = update;
        input.onchange = update;
        if(input.tagName === 'TEXTAREA') input.addEventListener('mousedown', event => {
            if(event.button !== 0) return;
            const rect = input.getBoundingClientRect();
            const scale = rect.height / input.offsetHeight || 1;
            const grip = 16 * scale;
            if(event.clientX < rect.right - grip || event.clientY < rect.bottom - grip) return;
            event.preventDefault();
            if(!collabCanMutateCanvas(true) || !collabCanEditNode(node.id, true)) return;
            startUndo();
            const startY = event.clientY, startHeight = input.offsetHeight;
            const resize = move => {
                if(!input.isConnected || !nodes.includes(node)) { finish(); return; }
                move.preventDefault();
                const height = Math.max(96, Math.round(startHeight + (move.clientY - startY) / scale));
                input.style.height = `${height}px`;
                node.comfyFieldHeights = {...node.comfyFieldHeights, [input.dataset.comfyNodeParam]:height};
            };
            const finish = () => {
                document.removeEventListener('mousemove', resize);
                document.removeEventListener('mouseup', finish);
                window.removeEventListener('blur', finish);
                finishUndo();
                scheduleSave();
            };
            document.addEventListener('mousemove', resize);
            document.addEventListener('mouseup', finish, {once:true});
            window.addEventListener('blur', finish, {once:true});
        });
    });
    el.querySelectorAll('[data-comfy-node-bool]').forEach(input => {
        input.onchange = event => {
            event.stopPropagation();
            startUndo();
            setComfyNodeFieldValue(node, input.dataset.comfyNodeBool, input.checked);
            finishUndo();
        };
    });
    el.querySelectorAll('[data-comfy-node-random]').forEach(button => {
        button.onclick = event => {
            event.preventDefault();
            event.stopPropagation();
            startUndo();
            node.runSettings = node.runSettings && typeof node.runSettings === 'object' ? node.runSettings : {};
            node.runSettings.comfyRandomActive = node.runSettings.comfyRandomActive || {};
            const fieldId = button.dataset.comfyNodeRandom;
            node.runSettings.comfyRandomActive[fieldId] = !smartComfyRandomActiveFor(node.runSettings, fieldId);
            if(activeSettingsSubject()?.id === node.id){
                settings = cloneSmartSettings(node.runSettings);
                renderDynamicParams();
            }
            finishUndo();
            render();
            scheduleSave();
        };
    });
}
function timelineUpstreamForNode(node){
    return typeof canvasTaskScopeInputNodes === 'function'
        ? canvasTaskScopeInputNodes(node)
        : (node?.inputNodeIds || []).map(id => nodes.find(item => item.id === id)).filter(Boolean);
}
function bindSmartDataVideoNode(el, node){
    if(!node || (!isSmartTableNode(node) && !isSmartTimelineNode(node))) return;
    const edit = () => { if(!collabCanMutateCanvas(true) || !collabCanEditNode(node.id, true)) return false; pushUndo(); return true; };
    if(isSmartTableNode(node)){
        el.querySelectorAll('[data-table-header]').forEach(input => input.addEventListener('change', e => {
            e.stopPropagation(); if(!edit()) return; node.columns[Number(input.dataset.tableHeader)] = input.value.slice(0,80); normalizeSmartDataVideoNode(node); render(); scheduleSave();
        }));
        el.querySelectorAll('[data-table-row][data-table-col]').forEach(input => input.addEventListener('change', e => {
            e.stopPropagation(); if(!edit()) return; const r=Number(input.dataset.tableRow), c=Number(input.dataset.tableCol); node.rows[r][c] = input.value.slice(0,2000); scheduleSave();
        }));
        el.querySelectorAll('[data-table-action]').forEach(btn => btn.addEventListener('click', e => {
            e.preventDefault(); e.stopPropagation(); if(!edit()) return;
            if(btn.dataset.tableAction === 'row') node.rows.push(node.columns.map(() => ''));
            else if(btn.dataset.tableAction === 'column'){ node.columns.push(`字段${node.columns.length + 1}`); node.rows.forEach(row => row.push('')); }
            else if(btn.dataset.tableAction === 'remove-row') node.rows.pop();
            render(); scheduleSave();
        }));
        return;
    }
    const current = () => window.SmartCanvasDataVideo?.timelineMedia?.(node, timelineUpstreamForNode(node)) || [];
    el.querySelectorAll('[data-timeline-field]').forEach(input => input.addEventListener('change', e => {
        e.stopPropagation(); if(!edit()) return;
        const kind = input.dataset.timelineKind; const index = Number(input.dataset.timelineIndex);
        const list = current().filter(item => kind === 'audio' ? item.kind === 'audio' : item.kind !== 'audio'); const clip = list[index];
        if(!clip) return; const saved = node.timelineClips.find(item => item.url === clip.url) || {...clip};
        saved[input.dataset.timelineField] = Number(input.value) || 0; node.timelineClips = [...node.timelineClips.filter(item => item.url !== clip.url), saved]; render(); scheduleSave();
    }));
    el.querySelectorAll('[data-timeline-move]').forEach(btn => btn.addEventListener('click', e => {
        e.preventDefault(); e.stopPropagation(); if(!edit()) return;
        const list = current().filter(item => item.kind !== 'audio'); const index = Number(btn.dataset.timelineIndex); const item = list[index]; if(!item) return;
        const order = list.map(x => x.url); const next = btn.dataset.timelineMove === 'up' ? index - 1 : index + 1; if(next < 0 || next >= order.length) return;
        [order[index], order[next]] = [order[next], order[index]]; node.timelineOrder = order; render(); scheduleSave();
    }));
    const caption = el.querySelector('.smart-timeline-caption');
    caption?.addEventListener('change', e => { e.stopPropagation(); if(!edit()) return; node.timelineCaption = caption.value.slice(0,500); scheduleSave(); });
    el.querySelectorAll('[data-timeline-setting]').forEach(input => input.addEventListener('change', e => { e.stopPropagation(); if(!edit()) return; node[`timeline${input.dataset.timelineSetting[0].toUpperCase()}${input.dataset.timelineSetting.slice(1)}`] = Math.round(Number(input.value) || 0); normalizeSmartDataVideoNode(node); render(); scheduleSave(); }));
    el.querySelector('.smart-timeline-export')?.addEventListener('click', async e => {
        e.preventDefault(); e.stopPropagation(); if(!collabCanMutateCanvas(true) || !collabCanEditNode(node.id, true)) return;
        const clips = current(); const visuals = clips.filter(item => item.kind !== 'audio'); if(!visuals.length){ toast('请先连接图片或视频素材'); return; }
        node.timelineExporting = true; node.timelineError = ''; render();
        try{
            const captionText = String(node.timelineCaption || '').trim();
            const total = visuals.reduce((sum, item) => sum + (Number(item.duration) || (item.kind === 'image' ? 3 : 5)), 0);
            const response = await fetch('/api/canvas-video-timeline/export', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({clips, width:node.timelineWidth, height:node.timelineHeight, fps:30, captions:captionText ? [{text:captionText, start:0, end:total}] : []})});
            const result = await response.json(); if(!response.ok) throw new Error(result.detail || '导出失败');
            node.timelineOutput = result; node.images = [{...result, kind:'video'}]; node.timelineStatus = '导出完成';
        }catch(error){ node.timelineError = error?.message || '导出失败'; toast(node.timelineError); }
        finally{ node.timelineExporting = false; render(); scheduleSave(); }
    });
}
