function isImageMaskMode(){ return imageEditMode === 'mask' || imageEditMode === 'protection-mask'; }
function setImageEditMode(mode, userTouched=false){
    closePreviewImageContextMenu();
    const editKind = mediaKindForItem(currentEditImage().image || {});
    const isVideoPreview = editKind === 'video';
    if(isVideoPreview && mode !== 'preview') mode = 'preview';
    if(userTouched) imageEditModeTouched = true;
    const prev = imageEditMode;
    if(mode !== prev){
        smartInk.finishInline(true);
        smartInk.finishStroke(null, true);
        smartGrid.split.end();
        smartGrid.endDrag();
        smartEditRevision++;
    }
    imageEditMode = ['preview','crop','outpaint','mask','protection-mask','ocr','brush','resize','grid'].includes(mode) ? mode : 'preview';
    if(prev === 'ocr' && imageEditMode !== 'ocr') smartOcr.leave();
    const cropCanvasEl = document.getElementById('cropCanvas');
    const previewStageEl = document.getElementById('previewStage');
    const editStageEl = document.getElementById('imageEditStage');
    const editPanelEl = document.querySelector('.image-edit-panel');
    const previewDownloadBtn = document.getElementById('previewDownloadBtn');
    const previewDownloadAllBtn = document.getElementById('previewDownloadAllBtn');
    const modeBar = document.querySelector('.image-edit-mode');
    const videoFrameTools = document.getElementById('videoFrameTools');
    const zoomLabel = document.getElementById('imageEditZoomLabel');
    const cancelBtn = document.getElementById('imageEditCancelBtn');
    const previewCopyBtn = document.getElementById('previewCopyBtn');
    const previewPhotoshopBtn = document.getElementById('previewPhotoshopBtn');
    const isPreview = imageEditMode === 'preview';
    const isOutpaint = imageEditMode === 'outpaint';
    const isOcr = imageEditMode === 'ocr';
    const isCompareNodePreview = smartPreview.comparingNode();
    imageEditModal?.classList.toggle('outpaint-redesign', isOutpaint);
    imageEditModal?.classList.toggle('ocr-redesign', isOcr);
    imageEditModal?.classList.toggle('compare-node-preview', isCompareNodePreview);
    if(!isPreview) smartPreview.suspend();
    cropCanvasEl.style.display = isPreview ? 'none' : '';
    previewStageEl.style.display = isPreview ? 'inline-flex' : 'none';
    editStageEl?.classList.toggle('preview-mode', isPreview);
    editPanelEl?.classList.toggle('video-preview-mode', isVideoPreview);
    if(previewDownloadBtn) previewDownloadBtn.style.display = isPreview ? 'inline-flex' : 'none';
    if(previewCopyBtn) previewCopyBtn.style.display = isPreview && !isVideoPreview ? 'inline-flex' : 'none';
    if(previewPhotoshopBtn) previewPhotoshopBtn.style.display = isPreview && !isVideoPreview ? 'inline-flex' : 'none';
    if(previewDownloadAllBtn) previewDownloadAllBtn.style.display = isPreview && !isVideoPreview && !isCompareNodePreview && previewDownloadGroupItems().length > 1 ? 'inline-flex' : 'none';
    if(modeBar) modeBar.style.display = isVideoPreview ? 'none' : '';
    if(videoFrameTools) videoFrameTools.style.display = isVideoPreview && isPreview ? 'flex' : 'none';
    if(zoomLabel) zoomLabel.style.display = isVideoPreview ? 'none' : '';
    if(cancelBtn){
        cancelBtn.style.display = '';
        cancelBtn.textContent = isVideoPreview ? '关闭' : tr('common.cancel');
    }
    cropCanvasEl.classList.toggle('mask-mode', isImageMaskMode());
    cropCanvasEl.classList.toggle('ocr-mode', imageEditMode === 'ocr');
    cropCanvasEl.classList.toggle('brush-mode', imageEditMode === 'brush');
    cropCanvasEl.classList.toggle('resize-mode', imageEditMode === 'resize');
    cropCanvasEl.classList.toggle('grid-mode', imageEditMode === 'grid');
    cropCanvasEl.classList.toggle('outpaint-mode', imageEditMode === 'outpaint');
    document.querySelectorAll('[data-image-edit-mode]').forEach(btn => btn.classList.toggle('active', btn.dataset.imageEditMode === imageEditMode));
    if(isOcr) document.querySelectorAll('.image-edit-mode [data-image-edit-mode]').forEach(btn => {
        const label = btn.querySelector('span')?.textContent || '';
        if(label){ btn.setAttribute('aria-label', label); btn.title = label; }
    });
    document.getElementById('imagePreviewTools').classList.toggle('active', isPreview && !isVideoPreview);
    document.getElementById('imageCropTools')?.classList.toggle('active', imageEditMode === 'crop');
    document.getElementById('imageMaskTools').classList.toggle('active', isImageMaskMode());
    document.getElementById('imageMaskHint').textContent = imageEditMode === 'protection-mask'
        ? '涂抹需要保护的产品区域，输出白色保护、黑色背景的 PNG 蒙版'
        : '涂抹要抹除的区域，应用后生成清理结果';
    document.getElementById('imageOcrTools')?.classList.toggle('active', isOcr);
    document.getElementById('imageBrushTools').classList.toggle('active', imageEditMode === 'brush');
    document.getElementById('imageResizeTools')?.classList.toggle('active', imageEditMode === 'resize');
    document.getElementById('imageGridTools').classList.toggle('active', imageEditMode === 'grid');
    smartGrid.sync();
    smartImageEditor.resizeControls();
    const outpaintBar = document.getElementById('outpaintActionBar');
    if(outpaintBar) outpaintBar.style.display = isOutpaint ? 'flex' : 'none';
    if(isOutpaint) syncOutpaintControls();
    const applyBtn = document.getElementById('imageEditApplyBtn');
    if(isPreview){
        document.getElementById('imageEditTitle').textContent = isCompareNodePreview
            ? smartCompareText('smart.compareNodePreviewTitle', '对比预览')
            : (isVideoPreview ? '预览视频' : tr('smart.previewImage'));
        document.getElementById('imageEditSub').textContent = isCompareNodePreview
            ? smartCompareText('smart.compareNodePreviewHint', '拖动中间滑块调整对比位置')
            : (isVideoPreview ? '' : tr('smart.previewHint'));
        applyBtn.style.display = 'none';
        refreshComparePanel();
    } else {
        smartImageEditor.refit(true);
        smartImageEditor.applyZoom();
        applyBtn.style.display = '';
        if(isOcr){
            document.getElementById('imageEditTitle').textContent = 'OCR 智能改字';
            document.getElementById('imageEditSub').textContent = '直接修改识别文字，只生成已修改内容';
            applyBtn.style.display = 'none';
        } else if(imageEditMode === 'protection-mask'){
            document.getElementById('imageEditTitle').textContent = '保护蒙版';
            document.getElementById('imageEditSub').textContent = '涂抹要保留的区域，生成后可下载并用于产品保护';
            applyBtn.innerHTML = '<i data-lucide="scan" class="w-4 h-4"></i><span>生成蒙版节点</span>';
        } else if(imageEditMode === 'resize'){
            document.getElementById('imageEditTitle').textContent = '缩放图片';
            document.getElementById('imageEditSub').textContent = '选择缩小倍数，应用会替换当前原图';
            applyBtn.innerHTML = `<i data-lucide="minimize-2" class="w-4 h-4"></i><span>应用缩放</span>`;
        } else {
            const icon = imageEditMode === 'crop' ? 'crop' : imageEditMode === 'outpaint' ? 'expand' : imageEditMode === 'mask' ? 'eraser' : imageEditMode === 'ocr' ? 'scan-text' : imageEditMode === 'brush' ? 'paintbrush' : 'grid-3x3';
            const labelKey = imageEditMode === 'crop' ? 'canvas.applyCrop' : imageEditMode === 'outpaint' ? 'canvas.applyOutpaint' : imageEditMode === 'mask' ? 'canvas.applyMask' : imageEditMode === 'ocr' ? 'canvas.applyBrush' : imageEditMode === 'brush' ? 'canvas.applyBrush' : 'canvas.applyGrid';
            const titleKey = imageEditMode === 'crop' ? 'canvas.cropImage' : imageEditMode === 'outpaint' ? 'canvas.outpaintImage' : imageEditMode === 'mask' ? 'canvas.maskEdit' : imageEditMode === 'ocr' ? 'canvas.brushEdit' : imageEditMode === 'brush' ? 'canvas.brushEdit' : 'canvas.modeGrid';
            const subKey = imageEditMode === 'crop' ? 'canvas.cropHint' : imageEditMode === 'outpaint' ? 'smart.outpaintHint' : imageEditMode === 'mask' ? 'canvas.maskHint2' : imageEditMode === 'ocr' ? 'canvas.brushHint' : imageEditMode === 'brush' ? 'canvas.brushHint' : 'canvas.gridHint';
            document.getElementById('imageEditTitle').textContent = tr(titleKey);
            document.getElementById('imageEditSub').textContent = tr(subKey);
            const applyLabel = smartGrid.joining() ? '输出拼接' : imageEditMode === 'mask' ? '执行抹除' : imageEditMode === 'ocr' ? '生成改字图片' : tr(labelKey);
            applyBtn.innerHTML = `<i data-lucide="${icon}" class="w-4 h-4"></i><span>${applyLabel}</span>`;
        }
        if((imageEditMode === 'crop' || isOutpaint) && smartImageEditor.ready()){
            resetCropBox();
            syncImageEditOverflow();
        }
    }
    resizeEditDrawCanvas();
    if(imageEditMode === 'grid') refreshGridSplitPreview();
    else if(imageEditMode === 'crop' || imageEditMode === 'resize' || imageEditMode === 'outpaint' || imageEditMode === 'ocr' || prev === 'grid') clearEditDrawing(true);
    if(isOcr){
        smartOcr.open();
        requestAnimationFrame(() => {
            if(imageEditMode !== 'ocr' || !imageEditModal.classList.contains('open')) return;
            smartImageEditor.refit(true);
            smartImageEditor.applyZoom();
            smartOcr.schedule();
        });
    }
    smartInk.refreshTools();
    updatePreviewNavButtons();
    refreshIcons();
}
function smartPreviewReferences(node, compareId){
    if(compareId){
        const compare = nodes.find(item => item.id === compareId && isSmartCompareNode(item));
        return compare ? smartCompareInputImages(compare) : [];
    }
    if(!node) return [];
    const fromRun = (Array.isArray(node.runInputRefs) ? node.runInputRefs : []).filter(item => item?.url);
    const fromNode = nodes.find(item => item.id === node.sourceNodeId)?.images || [];
    const uniqueImages = items => {
        const refs = new Map();
        for(const item of items){
            if(item?.url && mediaKindForItem(item) === 'image' && !refs.has(item.url)) refs.set(item.url, item);
        }
        return [...refs.values()];
    };
    const inputs = uniqueImages(fromRun.length ? fromRun : inputImagesFor(node));
    return inputs.length ? inputs : uniqueImages(fromNode);
}
