function outpaintImageModelEntries(){
    const entries = [];
    imageProviders().forEach(provider => {
        const seen = new Set();
        providerImageModels(provider.id).forEach(model => {
            const value = String(model || '').trim();
            if(!value || seen.has(value)) return;
            seen.add(value);
            entries.push({providerId:String(provider.id || ''), providerName:String(provider.name || provider.id || ''), model:value});
        });
    });
    return entries;
}
function outpaintModelEntry(providerId='', model='', entries=outpaintImageModelEntries()){
    const pid = String(providerId || '').trim();
    const value = String(model || '').trim();
    if(!value) return null;
    return entries.find(item => item.providerId === pid && item.model === value)
        || entries.find(item => item.model === value)
        || null;
}
function outpaintModelSelectionForNode(node){
    const entries = outpaintImageModelEntries();
    const sources = [node?.runSettings, settings];
    for(const source of sources){
        const match = outpaintModelEntry(source?.provider_id, source?.model, entries);
        if(match) return {provider_id:match.providerId, model:match.model};
    }
    const first = entries[0];
    return first ? {provider_id:first.providerId, model:first.model} : {provider_id:'', model:''};
}
function renderOutpaintModelMenu(){
    const menu = document.getElementById('outpaintModelOptions');
    if(!menu) return;
    const entries = outpaintImageModelEntries();
    if(!entries.length){
        menu.innerHTML = '<div class="outpaint-model-empty">暂无可用图片模型，请先在 API 设置中拉取模型。</div>';
        return;
    }
    const groups = [];
    const byProvider = new Map();
    entries.forEach(item => {
        if(!byProvider.has(item.providerId)){
            const group = {providerId:item.providerId, providerName:item.providerName, models:[]};
            byProvider.set(item.providerId, group);
            groups.push(group);
        }
        byProvider.get(item.providerId).models.push(item);
    });
    menu.innerHTML = groups.map(group => `
        <section class="outpaint-model-group" data-outpaint-provider-group="${escapeAttr(group.providerId)}">
            <div class="outpaint-model-group-title">${escapeHtml(group.providerName)}</div>
            ${group.models.map(item => {
                const active = item.providerId === outpaintModelSelection.provider_id && item.model === outpaintModelSelection.model;
                return `<button type="button" class="outpaint-model-option ${active ? 'active' : ''}" role="option" aria-selected="${active ? 'true' : 'false'}" data-outpaint-provider="${escapeAttr(item.providerId)}" data-outpaint-model="${escapeAttr(item.model)}"><span>${escapeHtml(item.model)}</span>${active ? '<i data-lucide="check"></i>' : ''}</button>`;
            }).join('')}
        </section>`).join('');
    menu.querySelectorAll('[data-outpaint-model]').forEach(button => {
        button.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            setOutpaintModelSelection(button.dataset.outpaintProvider || '', button.dataset.outpaintModel || '');
        });
    });
    refreshIcons();
}
function syncOutpaintModelControls(){
    const entries = outpaintImageModelEntries();
    const current = outpaintModelEntry(outpaintModelSelection.provider_id, outpaintModelSelection.model, entries);
    if(!current && entries.length){
        const fallback = outpaintModelSelectionForNode(currentEditImage().node);
        outpaintModelSelection = fallback;
    }
    const label = document.getElementById('outpaintModelLabel');
    const button = document.getElementById('outpaintModelBtn');
    const selected = outpaintModelEntry(outpaintModelSelection.provider_id, outpaintModelSelection.model, entries);
    if(label) label.textContent = selected?.model || '选择模型';
    const qualityControl = document.getElementById('outpaintQuality');
    if(qualityControl) qualityControl.disabled = !selected || !imageModelSupportsQuality({model:selected.model});
    if(button){
        button.classList.toggle('active', Boolean(selected));
        button.title = selected ? `${selected.providerName} · ${selected.model}` : '选择扩图模型';
    }
    renderOutpaintModelMenu();
}
function setOutpaintModelSelection(providerId='', model=''){
    const selected = outpaintModelEntry(providerId, model);
    if(!selected){
        toast('当前没有可用的图片模型，请先在 API 设置中拉取模型');
        return;
    }
    outpaintModelSelection = {provider_id:selected.providerId, model:selected.model};
    const menu = document.getElementById('outpaintModelMenu');
    menu?.classList.remove('open');
    document.getElementById('outpaintModelBtn')?.setAttribute('aria-expanded', 'false');
    syncOutpaintModelControls();
}
