    if(ratioLabel) ratioLabel.textContent = ratioInfo.key === 'auto' ? 'Auto' : ratioInfo.label;
    document.querySelectorAll('[data-outpaint-resolution]').forEach(btn => {
        btn.classList.toggle('active', String(btn.dataset.outpaintResolution || '').toLowerCase() === String(outpaintResolutionPreset || 'auto').toLowerCase());
    });
