    if(resolutionLabel){
        const key = String(outpaintResolutionPreset || 'auto').toLowerCase();
        resolutionLabel.textContent = key === 'auto' ? 'Auto' : key.toUpperCase();
    }
    outpaintCountPreset = normalizeOutpaintCount(outpaintCountPreset);
    const countButton = document.getElementById('outpaintCountBtn');
    if(countButton) countButton.classList.toggle('active', outpaintCountPreset > 1);
