async function uploadCroppedBlob(blob, name){
    const form = new FormData();
    form.append('files', blob, name);
    const response = await fetch('/api/ai/upload', {method:'POST', body:form});
    if(!response.ok){
        throw new Error(await smartResponseErrorMessage(response, '图片上传失败（' + response.status + '）'));
    }
    const file = (await response.json().catch(() => null))?.files?.[0];
    if(!file?.url) throw new Error('图片上传失败：服务器没有返回图片地址');
    return file;
}
function outpaintPreserveInfo(node){
    const raw = node?.outpaintPreserve;
    if(!raw || typeof raw !== 'object' || !String(raw.sourceUrl || '').trim()) return null;
    const canvasW = Math.round(Number(raw.canvasW || raw.canvasWidth) || 0);
    const canvasH = Math.round(Number(raw.canvasH || raw.canvasHeight) || 0);
    const sourceW = Math.round(Number(raw.sourceW || raw.sourceWidth) || 0);
    const sourceH = Math.round(Number(raw.sourceH || raw.sourceHeight) || 0);
    if(canvasW < 1 || canvasH < 1 || sourceW < 1 || sourceH < 1) return null;
    return {
        sourceUrl:String(raw.sourceUrl).trim(),
        x:Number(raw.x) || 0,
        y:Number(raw.y) || 0,
        sourceW,
        sourceH,
        canvasW,
        canvasH,
    };
}
async function uploadImageBlobs(blobs){
    const form = new FormData();
    blobs.forEach(item => form.append('files', item.blob, item.name));
    const data = await fetch('/api/ai/upload', {method:'POST', body:form}).then(r => r.json());
    return data.files || [];
}
async function exportSmartDrawingBoardNode(node){
    if(!isSmartDrawingBoardNode(node)) return false;
    if(!collabCanMutateCanvas(true) || !collabCanEditNode(node.id, true)) return false;
    const drawingApi = window.SmartDrawingBoard;
    if(!drawingApi?.hasStrokes?.(node)){
        toast(tr('smart.drawingBoardNothingToExport'));
        return false;
    }
    const outputSignature = state => JSON.stringify({
        width:Number(state?.width) || 0,
        height:Number(state?.height) || 0,
        background:state?.background || 'white',
        strokes:Array.isArray(state?.strokes) ? state.strokes : []
    });
    const sourceState = outputSignature(node.drawingBoard);
    const blob = await drawingApi.toBlob(node);
    if(!blob) throw new Error(tr('smart.drawingBoardExportFailed'));
    const name = 'hand-drawing-' + Date.now() + '.png';
    const uploaded = await uploadImageBlobs([{blob, name}]);
    const file = (uploaded || []).find(item => item?.url);
    if(!file) throw new Error(tr('smart.drawingBoardExportFailed'));
    const size = drawingApi.logicalSize?.(node) || {width:1024, height:768};
    pushUndo();
    node.images = [{
        ...file,
        kind:'image',
        name:file.name || name,
        natural_w:Number(file.natural_w || file.width || size.width),
        natural_h:Number(file.natural_h || file.height || size.height),
        width:Number(file.width || size.width),
        height:Number(file.height || size.height)
    }];
    node.drawingBoard = node.drawingBoard || drawingApi.defaultState?.() || {};
    node.drawingBoard.dirty = outputSignature(node.drawingBoard) !== sourceState;
    node.drawingBoard.outputAt = Date.now();
    node.outputKind = 'image';
    render();
    scheduleSave();
    toast(node.drawingBoard.dirty ? tr('smart.drawingBoardExportDoneWithChanges') : tr('smart.drawingBoardExportDone'));
    return true;
}
function replaceEditedImage(file, extra={}){
    const {node, index} = currentEditImage();
    if(!node || !file) return false;
    // 其它编辑动作会让本次扩图的原图定位关系失效。
    delete node.outpaintPreserve;
    node.images[index] = {
        ...(node.images[index] || {}), ...file,
        originalLocalUrl:file.url, localUrl:file.url, sourceUrl:file.url,
        local_url:file.url, source_url:file.url,
        kind:file.kind || mediaKindForItem(file), natural_w:0, natural_h:0, ...extra
    };
    if(!extra.localRepair) delete node.images[index].localRepair;
    if((node.images || []).length === 1){ delete node.w; delete node.h; }
    selectedId = node.id; selectedImage = {nodeId:node.id, index};
    return true;
}
function applyOutpaintSizeToSmartParams(width, height, subject=currentEditImage().node){
    const w = Math.max(1, Math.round(Number(width) || 0));
    const h = Math.max(1, Math.round(Number(height) || 0));
    if(!w || !h) return;
    if(!subject || !isSmartImageNode(subject)) return;
    subject.outpaintSize = {width:w, height:h};
    subject.runSettings = withOutpaintDisplaySettings(subject, cloneSmartSettings(subject.runSettings || settings));
    if(activeSettingsSubject()?.id === subject.id){
        settings = smartSettingsForNode(subject);
        renderDynamicParams();
    }
}
function smartEditOutputName(edit, mode){
    if(mode === 'crop') return (edit.image.name || 'image').replace(/\.[^.]+$/, '') + '_crop.png';
    const name = downloadNameForMediaItem(edit.image, 'image');
    const base = safeExportFileName(name.replace(/\.[^.]+$/, ''), 'image');
    return base + '_resize_' + Math.round(edit.resizeBy * 100) + 'pct.png';
}
function commitSmartCropOrResize(edit, mode, output, file){
    const {node, image, index} = edit;
    const {width, height} = output;
    const dims = {kind:'image', natural_w:width, natural_h:height, width, height};
    pushUndo();
    if(mode === 'crop' && edit.localRepair){
        const {x, y} = output.rect;
        const region = {version:1, id:uid('repair'), sourceNodeId:node.id, sourceImageIndex:index,
            sourceUrl:smartOriginalMediaUrl(image), sourceWidth:edit.sourceW, sourceHeight:edit.sourceH,
            x, y, width, height, cropUrl:file.url, createdAt:Date.now()};
        const rect = nodeRect(node);
        const name = (image.name || 'image').replace(/\.[^.]+$/, '') + '_局部.png';
        const patch = {...file, ...dims, name, localRepair:region};
        const cropped = createNode(rect.x + rect.width + 64, rect.y, [patch], {skipUndo:true, skipRender:true, skipSave:true});
        if(!cropped) return;
        cropped.title = '局部修复 · 裁剪';
        addConnection(node.id, cropped.id, 'flow');
    } else {
        const extra = mode === 'crop' ? dims : {...dims, role:image.role || ''};
        if(!replaceEditedImage(file, extra)) return;
    }
    closeImageEditor();
    render();
    scheduleSave();
    if(mode === 'crop' && edit.localRepair) toast('已保留原图并裁出局部，可连接绘画节点修改');
}
