    const rawIndex = raw?.index ?? raw?.imageIndex ?? raw?.image_index;
    const imageIndex = Number(rawIndex);
    if(!nodeId || !Number.isInteger(imageIndex) || imageIndex < 0) return null;
    const owner = nodes.find(node => node.id === nodeId);
    if(!owner) return null;
    const selectedNodes = (selectedIdsValue || []).map(id => nodes.find(node => node.id === id)).filter(Boolean);
