            selectedNodeIds:[],
            targetNodeId:'',
            sourceNodeIds:[],
            formalInputNodeIds:[],
            upstreamNodeIds:[],
            referenceImages:[],
            generationSettings:canvasTaskScopeGenerationSettings(null)
