        sourceNodeIds:sourceNodes.map(node => node.id),
        formalInputNodeIds:directInputs.map(node => node.id),
        upstreamNodeIds:canvasTaskScopeUpstreamIds(reusableTarget ? [reusableTarget] : selected),
        selectedImage:canvasTaskScopeSelectedImage(options, selectedNodeIds),
        selectedReferenceKeys:[],
