        selected_node_ids:Array.isArray(scope?.selectedNodeIds) ? scope.selectedNodeIds.slice() : [],
        target_node_id:String(scope?.targetNodeId || ''),
        source_node_ids:Array.isArray(scope?.sourceNodeIds) ? scope.sourceNodeIds.slice() : [],
        formal_input_node_ids:Array.isArray(scope?.formalInputNodeIds) ? scope.formalInputNodeIds.slice() : [],
        upstream_node_ids:Array.isArray(scope?.upstreamNodeIds) ? scope.upstreamNodeIds.slice() : [],
