async function comfyNameForRef(ref, workflowContext={}){
    if(ref.comfy_name) return ref.comfy_name;
    const node = ref.nodeId ? nodes.find(n => n.id === ref.nodeId) : null;
    const appId = String(workflowContext?.comfyAppId || workflowContext?.workflowAppId || node?.workflowAppId || node?.runSettings?.comfyAppId || settings?.comfyAppId || '').trim();
    const workflowName = String(workflowContext?.comfyWorkflow || workflowContext?.workflowRef || node?.workflowRef || settings?.comfyWorkflow || '').trim();
    const response = await fetch(ref.url);
    if(!response.ok) return ref.name || ref.url;
    const blob = await response.blob();
    const form = new FormData();
    form.append('files', blob, ref.name || 'smart-ref.png');
    if(appId) form.append('app_id', appId);
    if(workflowName) form.append('workflow_json', workflowName);
    const data = await fetch('/api/upload', {method:'POST', body:form}).then(async r => {
        if(!r.ok) throw new Error(await r.text());
        return r.json();
    });
    const name = data.files?.[0]?.comfy_name || ref.name || ref.url;
    const image = node?.images?.find(img => img.url === ref.url) || (nodes || []).flatMap(n => n.images || []).find(img => img?.url === ref.url);
    if(image) image.comfy_name = name;
    ref.comfy_name = name;
    return name;
}
function smartPendingTasks(node){
    if(!node || !Array.isArray(node.pendingTasks)) return [];
    return node.pendingTasks.filter(task => task && task.taskId);
}
function isInvalidImageTaskRecovery(task){
    if(!task?.recoverTaskId) return false;
    const error = String(task.error || '');
    const recoveryId = String(task.recoverTaskId || '');
    if(!error || !recoveryId) return false;
    const escapedId = recoveryId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const isRequestId = new RegExp(
        `(?:request[_ ]?id)\\s*[=:：]\\s*${escapedId}(?:\\b|[)\\]，。])`,
        'i'
    ).test(error);
    const isQuotaRejection = /insufficient[_ ]user[_ ]quota|insufficient[_ ]user[_ ]balance|quota\s*(?:exceeded|exhausted)|预扣费额度|额度不足|余额不足|insufficient balance/i.test(error);
    return isRequestId || isQuotaRejection;
}
function migrateInvalidImageTaskRecoveries(node){
    if(!node || !Array.isArray(node.pendingTasks)) return false;
    const invalid = node.pendingTasks.filter(isInvalidImageTaskRecovery);
    if(!invalid.length) return false;
    const invalidError = String(invalid.find(task => task.error)?.error || '生图任务失败');
    const remaining = node.pendingTasks.filter(task => !invalid.includes(task));
    if(remaining.length){
        node.pendingTasks = remaining;
        node.pending = Math.max(remaining.length, Number(node.pending || 0) || remaining.length);
        node.running = false;
        return true;
    }
    delete node.pendingTasks;
    node.pending = 0;
    node.running = false;
    node.queued = false;
    node.runError = node.runError || invalidError;
    node.runFinishedAt = Number(node.runFinishedAt || 0) || nowMs();
    if(!node.runStartedAt) node.runStartedAt = node.runFinishedAt;
    node.runElapsedMs = Math.max(0, node.runFinishedAt - Number(node.runStartedAt || node.runFinishedAt));
    node.runTimerHidden = false;
    return true;
}
class JimengPendingSignal extends Error {
    constructor(info){
        const data = info || {};
        super(data.message || '即梦任务排队中，可继续等待或手动查询');
        this.jimengPending = true;
        this.submitId = data.submitId || data.submit_id || '';
        this.kind = data.kind || 'image';
        this.queueInfo = data.queueInfo || data.queue_info || {};
    }
}
class ImageTaskRecoverSignal extends Error {
    constructor(info){
        const data = info || {};
        super(data.message || '任务未丢失，可稍后手动查询结果');
        this.imageTaskRecover = true;
        this.taskId = data.taskId || data.task_id || '';
        this.recoverTaskId = data.recoverTaskId || data.upstream_task_id || data.upstreamTaskId || '';
        this.providerId = data.providerId || data.provider_id || '';
        this.kind = data.kind || 'image';
    }
}
function extractUpstreamTaskId(text){
    const match = String(text || '').match(/(?:task_id|taskId|task id)\s*[=:：]\s*([A-Za-z0-9_.:-]+)/i);
    return match ? match[1] : '';
}
function extractImageRecoveryId(text){
    const match = String(text || '').match(/恢复编号\s*[：:]\s*(img-[A-Za-z0-9-]+)/i);
    return match ? match[1] : '';
}
const activeJimengPolls = new Set();
// 即梦提交接口可能先返回云端排队任务；一分钟才查一次会让画布看起来像卡死。
// 先快速确认，之后以 5 秒间隔续查，既能及时出图也不会高频轰炸上游。
const JIMENG_POLL_INTERVAL = 5000;
const JIMENG_POLL_MAX = 1440;
function jimengQueueText(queueInfo){
    const qi = queueInfo || {};
    const idx = qi.queue_idx;
    const len = qi.queue_length;
    if(idx != null && len != null) return `即梦云端排队中（第 ${idx}/${len} 位）`;
    return '即梦云端生成中';
}
function setNodeJimengPending(node, signal){
    if(!node || !signal || !signal.submitId) return;
    const prev = node.jimengPending && node.jimengPending.submitId === signal.submitId ? node.jimengPending : null;
    node.jimengPending = {
        submitId:signal.submitId,
        localRepair:node.localRepairRunContext||null,
        kind:signal.kind || (prev && prev.kind) || 'image',
        queueInfo:signal.queueInfo || (prev && prev.queueInfo) || {},
        message:signal.message || (prev && prev.message) || '',
        startedAt:(prev && prev.startedAt) || nowMs(),
        updatedAt:nowMs(),
        querying:prev ? prev.querying : false
    };
    node.running = false;
    node.pending = 0;
    delete node.pendingTasks;
    if(!node.runStartedAt) node.runStartedAt = node.jimengPending.startedAt;
    delete node.runFinishedAt;
    delete node.runElapsedMs;
    node.runTimerHidden = false;
    render({nodeIds:[node.id]});
    scheduleSave();
    startJimengPoll(node);
}
function handleJimengPendingSignal(node, e){
    if(!(e && e.jimengPending && e.submitId)) return false;
    setNodeJimengPending(node, e);
    toast((e.message || jimengQueueText(e.queueInfo)).slice(0, 160));
    return true;
}
async function finalizeJimengPending(node, urls, kind='image'){
    if(!node) return false;
    const ext = kind === 'video' ? 'mp4' : kind === 'audio' ? 'mp3' : kind === 'text' ? 'txt' : 'png';
    const additions = (urls || []).map((item, i) => {
        const url = typeof item === 'string' ? item : item?.url || '';
        const itemKind = (typeof item === 'object' && item.kind) || kind;
        return stripImageGenerationMeta(copyMediaSizeFields(item, {url, name:(typeof item === 'object' && item.name) || `output-${i + 1}.${ext}`, kind:itemKind, generatedResult:true}));
    }).filter(item => item.url);
    if(!additions.length) return false;
    const repairedAdditions=typeof localRepairApplyMeta==='function'?localRepairApplyMeta(additions,node.jimengPending?.localRepair):additions;
    delete node.jimengPending;
    delete node.runError;
    replaceOutputsToNodeWithHistory(node, repairedAdditions, kind, null, {skipShift:true});
    node.running = false;
    node.pending = 0;
    node.runFinishedAt = nowMs();
    if(!node.runStartedAt) node.runStartedAt = node.runFinishedAt;
    node.runElapsedMs = Math.max(0, node.runFinishedAt - Number(node.runStartedAt || node.runFinishedAt));
    node.runTimerHidden = false;
    delete node.outpaintPreserve;
    render({nodeIds:[node.id], connectionsChanged:true});
    scheduleSave();
    return true;
}
async function applyJimengQueryResult(node, data){
    if(!node || !data) return false;
    if(data.status === 'succeeded'){
        const kind = data.kind || node.jimengPending?.kind || 'image';
        return finalizeJimengPending(node, data.urls || [], kind);
    }
    if(data.status === 'failed'){
        delete node.jimengPending;
        node.running = false;
        node.pending = 0;
        toast((data.error || '即梦任务失败').slice(0, 160));
        render({nodeIds:[node.id]});
        scheduleSave();
        return true;
    }
    if(node.jimengPending){
        node.jimengPending.queueInfo = data.queue_info || node.jimengPending.queueInfo || {};
        node.jimengPending.message = data.message || node.jimengPending.message || '';
        node.jimengPending.updatedAt = nowMs();
    }
    render({nodeIds:[node.id]});
    scheduleSave();
    return false;
}
async function fetchJimengQuery(submitId, kind){
    return fetch('/api/jimeng/query-media', {
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({submit_id:submitId, kind:kind || 'image'})
    }).then(async r => { if(!r.ok) throw new Error(await r.text()); return r.json(); });
}
async function queryJimengNow(nodeId){
    const node = nodes.find(n => n.id === nodeId);
    if(!node || !node.jimengPending || !node.jimengPending.submitId) return;
    if(node.jimengPending.querying) return;
    const submitId = node.jimengPending.submitId;
    const kind = node.jimengPending.kind || 'image';
    node.jimengPending.querying = true;
    render({nodeIds:[node.id]});
    try {
        const data = await fetchJimengQuery(submitId, kind);
        if(node.jimengPending?.submitId === submitId) await applyJimengQueryResult(node, data);
    } catch(e){
        toast((e.message || '查询失败').slice(0, 160));
    } finally {
        if(node.jimengPending) node.jimengPending.querying = false;
        render();
    }
}
function providerIdForSmartTask(node, task){
    return task?.providerId || node?.runSettings?.provider_id || settings.provider_id || 'comfly';
}
async function fetchImageTaskQuery(providerId, taskId, historySource='canvas'){
    return fetch('/api/image-task-query', {
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({provider_id:providerId || 'comfly', task_id:taskId, history_source:historySource, project_id:currentSmartProjectId()})
    }).then(async r => {
        if(!r.ok) throw new Error(await r.text());
        return r.json();
    });
}
async function recoverUnparsedImageNow(nodeId, recoveryId){
    const node = nodes.find(n => n.id === nodeId);
    if(!node || !recoveryId || node.recoveryQuerying) return;
    node.recoveryQuerying = true;
    render();
    try {
    const response = await fetch(`/api/image-result-recovery/${encodeURIComponent(recoveryId)}?history_source=canvas&project_id=${encodeURIComponent(currentSmartProjectId())}`, {method:'POST'});
        if(!response.ok) throw new Error((await response.json().catch(() => ({}))).detail || '恢复失败');
        const data = await response.json();
        const source = data.image_items?.length ? data.image_items : (data.images || []);
        if(node.runSettings?.productFidelity?.enabled && !data.product_fidelity) throw new Error('恢复图片尚未完成产品保护处理，请保留恢复编号并重新打开该任务');
        if(data.product_fidelity) acceptProductFidelityResult(node, data.product_fidelity);
        if(node.runSettings?.productRetouch && !data.product_retouch)throw new Error('精修结果尚未完成质量检查，请稍后重新查询');
        if(data.product_retouch)acceptProductRetouchResult(node,data.product_retouch);
        const additions = resultMediaUrls(source).map((item, index) => {
            const url = typeof item === 'string' ? item : item?.url || '';
            return stripImageGenerationMeta(copyMediaSizeFields(item, {
                url,
                name:(typeof item === 'object' && item.name) || `recovered-${index + 1}.png`,
                kind:'image',
                generatedResult:true,
                outpaintCenterLocked:item?.outpaintCenterLocked === true,
                outpaintOriginalRedrawn:item?.outpaintOriginalRedrawn === true
            }));
        }).filter(item => item.url);
        if(!additions.length) throw new Error('恢复记录中没有可显示的图片');
        replaceOutputsToNodeWithHistory(node, additions, 'image', null, {skipShift:true});
        delete node.runError;
        delete node.recoveryQuerying;
        node.running = false;
        node.pending = 0;
        node.runFinishedAt = nowMs();
        render();
        scheduleSave();
        toast(`已恢复 ${additions.length} 张图片，没有再次调用模型`);
    } catch(error) {
        delete node.recoveryQuerying;
        render();
        toast((error?.message || '恢复失败').slice(0, 180));
    }
}
async function querySmartImageTaskNow(nodeId, localTaskId){
    const node = nodes.find(n => n.id === nodeId);
    if(!node) return;
    const task = smartPendingTasks(node).find(item => item.taskId === localTaskId) || smartRecoverableImageTask(node);
    if(!task || task.querying) return;
    const recoverTaskId = task.recoverTaskId || extractUpstreamTaskId(task.error || '');
    if(!recoverTaskId){
        toast('没有任务 ID，无法查询');
        return;
    }
    task.querying = true;
    task.recoverTaskId = recoverTaskId;
    render();
    try {
        const data = await fetchImageTaskQuery(providerIdForSmartTask(node, task), recoverTaskId, 'canvas');
        if(data.status === 'succeeded' && node.runSettings?.productFidelity?.enabled && !data.product_fidelity) throw new Error('恢复图片缺少产品保护检查，已停止将未保护图片写入节点');
        if(data.product_fidelity) acceptProductFidelityResult(node, data.product_fidelity);
        if(data.status === 'succeeded' && node.runSettings?.productRetouch && !data.product_retouch)throw new Error('精修结果尚未完成质量检查，请稍后重新查询');
        if(data.product_retouch)acceptProductRetouchResult(node,data.product_retouch);
        if(data.status === 'succeeded'){
            const taskImages = resultMediaUrls(data.image_items?.length ? data.image_items : (data.images?.length ? data.images : data));
            if(!taskImages.length){
                const message = '任务查询显示成功，但没有返回可显示的图片';
                task.failed = true;
                task.error = message;
                task.querying = false;
                node.runError = message;
                node.running = false;
                toast(message);
                return;
            }
            task.failed = false;
            task.querying = false;
            finalizeSmartPendingTask(node, task.taskId, taskImages, task.kind || 'image');
            if(!node.pending && smartPendingTasks(node).length === 0) delete node.outpaintPreserve;
            render();
            scheduleSave();
            return;
        }
        if(data.status === 'failed'){
            task.error = data.error || tr('smart.errRunFailed');
            toast(task.error.slice(0, 160));
        } else {
            task.error = data.message || '任务仍在生成中，请稍后再查询';
            toast(task.error);
        }
    } catch(e){
        task.error = e.message || '查询失败';
        toast(task.error.slice(0, 160));
    } finally {
        const latest = smartPendingTasks(node).find(item => item.taskId === localTaskId);
        if(latest) latest.querying = false;
        render();
        scheduleSave();
    }
}
function startJimengPoll(node){
    if(!node || !node.jimengPending || !node.jimengPending.submitId) return;
    const submitId = node.jimengPending.submitId;
    if(activeJimengPolls.has(submitId)) return;
    activeJimengPolls.add(submitId);
    const nodeId = node.id;
    const taskCanvasId = canvasId;
    (async () => {
        try {
            for(let i = 0; i < JIMENG_POLL_MAX; i++){
                const delay = i === 0 ? 800 : JIMENG_POLL_INTERVAL;
                await new Promise(resolve => setTimeout(resolve, delay));
                if(canvasId !== taskCanvasId) return;
                const cur = nodes.find(n => n.id === nodeId);
                if(!cur || !cur.jimengPending || cur.jimengPending.submitId !== submitId) return;
                if(cur.jimengPending.querying) continue;
                let data;
                try {
                    data = await fetchJimengQuery(submitId, cur.jimengPending.kind || 'image');
                } catch(err){ continue; }
                if(canvasId !== taskCanvasId || cur.jimengPending?.submitId !== submitId) return;
                const done = await applyJimengQueryResult(cur, data);
                if(done) return;
                const after = nodes.find(n => n.id === nodeId);
                if(!after || !after.jimengPending || after.jimengPending.submitId !== submitId) return;
            }
        } finally {
            activeJimengPolls.delete(submitId);
        }
    })();
}
function resumeJimengPendingNodes(){
    nodes.filter(n => n && n.jimengPending && n.jimengPending.submitId).forEach(n => {
        n.jimengPending.querying = false;
        startJimengPoll(n);
    });
}
async function pollSmartCanvasTask(taskId, options={}){
    if(!taskId) throw new Error(tr('smart.errRunFailed'));
    if(activeSmartTaskPolls.has(taskId)) return activeSmartTaskPolls.get(taskId);
    // 后端单次生图默认查询 1 小时（不含排队与下载），前端额度要明显更长，
    // 且排队等待并发名额的时间不计入，避免平台已成功但画布放弃了任务。
    const classifyTask = task => {
        const decision = XiaomeiDispatchKernel.pollDecision(task);
        if(decision.state === 'succeeded') return {action:'resolve',value:task.result || {}};
        if(decision.state === 'empty') return {action:'reject',error:new Error(decision.message)};
        if(decision.state === 'jimeng_pending') return {
            action:'reject',
            error:new JimengPendingSignal({submitId:task.submit_id, kind:task.kind, queueInfo:task.queue_info, message:task.message}),
        };
        if(decision.state === 'cancelled'){
            const error = new Error(decision.message || '生图已取消');
            error.cancelledTask = true;
            return {action:'reject', error};
        }
        if(decision.state === 'failed'){
            const terminalError = new Error(decision.message || tr('smart.errRunFailed'));
            if(decision.terminal){
                terminalError.terminalTask = true;
                terminalError.startedAt = task.started_at || task.created_at || 0;
                terminalError.finishedAt = task.finished_at || task.updated_at || 0;
                return {action:'reject', error:terminalError};
            }
            const recoverTaskId = decision.recoverId || extractUpstreamTaskId(task.error || '');
            if(recoverTaskId) return {
                action:'reject',
                error:new ImageTaskRecoverSignal({taskId, recoverTaskId, providerId:task.provider_id, kind:'image', message:decision.message || tr('smart.errRunFailed')}),
            };
            return {action:'reject',error:new Error(decision.message || tr('smart.errRunFailed'))};
        }
        return null;

    };
    const promise = XiaomeiImageTaskClient.pollImageTask(taskId, {
        initialDelayMs:0,
        intervalMs:2000,
        timeoutMs:15000,
        maxAttempts:2100,
        isQueuedTask(task){
            return String(task?.status || '').trim().toLowerCase() === 'queued';
        },
        async onTimeout({fetchTask}){
            // 超时后最后查一次；若后端已记录平台任务号，转成“可稍后查询”而不是丢弃任务。
            try {
                const task = await fetchTask();
                const decision = classifyTask(task);
                if(decision) return decision;
                const recoverTaskId = task?.upstream_task_id || extractUpstreamTaskId(task?.error || '');
                if(recoverTaskId) return {
                    action:'reject',
                    error:new ImageTaskRecoverSignal({taskId, recoverTaskId, providerId:task.provider_id, kind:'image', message:tr('smart.errRunTimeout')}),
                };
            } catch(_) {
                // 最后一次查询失败时沿用原来的超时提示。
            }
            return null;
        },
        maxNetworkFailures:15,
        fallbackMessage:tr('smart.errRunFailed'),
        timeoutMessage:tr('smart.errRunTimeout'),
        onHttpError(error){
            if(error?.status === 404) return new Error('画布任务已失效，可能服务刚刚重启或任务已过期，请重新生成');
            return error;
        },
        onTaskUpdate(task, context){
            if(typeof options.onTaskUpdate === 'function') return options.onTaskUpdate(task, context);
            return null;
        },
        classifyTask,
    });
    activeSmartTaskPolls.set(taskId, promise);
    try {
        return await promise;
    } finally {
        activeSmartTaskPolls.delete(taskId);
    }
}
function finalizeSmartPendingTask(node, taskId, images, kind='image'){
    if(!node || !taskId) return;
    node = nodes.find(item => item.id === node.id);
    if(!node || !smartPendingTasks(node).some(task => task.taskId === taskId)) return;
    const localRepairTask=smartPendingTasks(node).find(task=>task.taskId===taskId)?.localRepair;
    node.pendingTasks = smartPendingTasks(node).filter(task => task.taskId !== taskId);
    node.pending = node.pendingTasks.length;
    const ext = kind === 'video' ? 'mp4' : kind === 'audio' ? 'mp3' : kind === 'text' ? 'txt' : 'png';
    const mediaItems = resultMediaUrls(images);
    const existing = cleanHistoryImages(node.images || []);
    const seen = new Set(existing.map(img => `${img.kind || ''}|${img.url || ''}`));
    const additions = cleanHistoryImages((mediaItems || []).map((item, i) => {
        const url = typeof item === 'string' ? item : item?.url || '';
        const itemKind = (typeof item === 'object' && item.kind) || kind;
        return stripImageGenerationMeta(copyMediaSizeFields(item, {url, name:(typeof item === 'object' && item.name) || `output-${i + 1}.${ext}`, kind:itemKind, generatedResult:true,
            outpaintCenterLocked:item?.outpaintCenterLocked === true, outpaintOriginalRedrawn:item?.outpaintOriginalRedrawn === true}));
    }).filter(item => item.url)).filter(item => {
        const key = `${item.kind || ''}|${item.url || ''}`;
        if(seen.has(key)) return false;
        seen.add(key);
        return true;
    });
    node.images = [...existing, ...(localRepairTask&&typeof localRepairApplyMeta==='function'?localRepairApplyMeta(additions,localRepairTask):additions)];
    if(additions.length){
        delete node.runError;
        delete node.batchGenerationCancelled;
    }
    if(additions.length) node.outputKind = kind;
    if(!node.pending && smartPendingTasks(node).length === 0){
        delete node.pendingTasks;
        node.runFinishedAt = Number(node._taskTimingFinish || 0) || nowMs();
        node.runStartedAt = Number(node._taskTimingStart || 0) || node.runStartedAt || node.runFinishedAt;
        node.runElapsedMs = Math.max(0, node.runFinishedAt - Number(node.runStartedAt || node.runFinishedAt));
        delete node._taskTimingStart;
        delete node._taskTimingFinish;
        node.runTimerHidden = false;
        node.running = false;
        node.title = node.images.length > 1 ? (kind === 'video' ? 'Videos' : kind === 'audio' ? 'Audios' : kind === 'text' ? 'Texts' : 'Group') : (kind === 'video' ? 'Video' : kind === 'audio' ? 'Audio' : kind === 'text' ? 'Text' : 'Image');
        if(node.images.length > 1 && (!Number.isFinite(Number(node.scale)) || Number(node.scale) === MEDIA_NODE_DEFAULT_SCALE || Number(node.scale) === MEDIA_GROUP_PREVIOUS_DEFAULT_SCALE)) node.scale = MEDIA_GROUP_DEFAULT_SCALE;
        else node.scale = mediaNodeDefaultScale(node);
        // 异步结果全部返回后，自动节点按真实比例收紧；仅保留用户亲自拉伸过的尺寸。
        if(node.manualSize !== true){
            delete node.w;
            delete node.h;
        }
    }
}
async function resumeSmartPendingNode(node, logContext={}){
    node = liveSmartNode(node);
    const tasks = smartPendingTasks(node);
    if(!node || !tasks.length) return;
    const taskCanvasId = canvasId;
    const nodeId = node.id;
    const currentTask = taskId => {
        if(canvasId !== taskCanvasId) return null;
        const currentNode = nodes.find(item => item.id === nodeId);
        const current = smartPendingTasks(currentNode).find(item => item.taskId === taskId);
        if(!current) return null;
        node = currentNode;
        return current;
    };
    const logTaskFailure = (message, task) => {
        if(!logContext?.run || !message) return;
        const runMs = Math.max(0, nowMs() - Number(logContext.runLogStart || nowMs()));
        addSmartGenerationLog({
            run:logContext.run,
            outputs:[],
            runMs,
            error:message
        });
    };
    node.pending = tasks.length;
    node.running = false;
    render({nodeIds:[node.id]});
    const failures = [];
    await Promise.all(tasks.map(async task => {
        if(task.failed && task.recoverTaskId) return;
        try {
            const updateTask = remoteTask => {
                    const current = currentTask(task.taskId);
                    if(!current) return;
                    const status = String(remoteTask?.status || remoteTask?.task_status || '').trim().toLowerCase();
                    const message = String(remoteTask?.message || '').trim();
                    let changed = false;
                    const progressData = {};
                    [
                        'status', 'task_status', 'message', 'progress', 'progress_percent',
                        'progressPercentage', 'percentage', 'percent', 'progress_value',
                        'progressValue', 'completion', 'completed_percent', 'completed',
                        'completed_count', 'current', 'done', 'finished', 'total',
                        'total_count', 'count', 'target', 'startedAt', 'started_at',
                        'createdAt', 'created_at', 'queueInfo', 'queue_info', 'queue',
                        'progress_source', 'progress_error', 'progress_node_id',
                        'progress_node_type', 'completed_nodes', 'total_nodes',
                        'prompt_id', 'comfy_backend', 'finished_at', 'updated_at'
                    ].forEach(key => {
                        if(remoteTask?.[key] === undefined) return;
                        progressData[key] = remoteTask[key];
                        if(current[key] !== remoteTask[key]){
                            current[key] = remoteTask[key];
                            changed = true;
                        }
                    });
                    if(Object.keys(progressData).length) current.progressData = progressData;
                    if(status && current.status !== status){
                        current.status = status;
                        changed = true;
                    }
                    if(message && current.message !== message){
                        current.message = message;
                        changed = true;
                    }
                    // 同批任务的状态与等待时间刷新合并到下一帧，不重建节点 DOM。
                    if(changed || status === 'running' || status === 'processing' || status === 'in_progress') requestSmartProgressRender();
            };
            const result = task.executor==='comfy'
                ? await waitSmartComfyTaskResult(task.taskId,updateTask)
                : await pollSmartCanvasTask(task.taskId,{onTaskUpdate:updateTask});
            if(!currentTask(task.taskId)) return;
            const taskImages = resultMediaUrls(result?.image_items?.length ? result.image_items : (result?.images?.length ? result.images : result));
            if(node.runSettings?.productRetouch && !result?.product_retouch)throw new Error('精修结果缺少质量检查，请保留任务编号后重新查询');
            if(result?.product_fidelity) acceptProductFidelityResult(node, result.product_fidelity);
            if(result?.product_retouch && typeof acceptProductRetouchResult === 'function') acceptProductRetouchResult(node, result.product_retouch);
            if(!currentTask(task.taskId)) return;
            const taskStartedAt = Number(task.started_at || task.created_at || 0);
            const taskFinishedAt = Number(task.finished_at || task.updated_at || 0);
            if(taskStartedAt > 0){
                const started = taskStartedAt < 100000000000 ? taskStartedAt * 1000 : taskStartedAt;
                node._taskTimingStart = Math.min(Number(node._taskTimingStart || started), started);
            }
            if(taskFinishedAt > 0){
                const finished = taskFinishedAt < 100000000000 ? taskFinishedAt * 1000 : taskFinishedAt;
                node._taskTimingFinish = Math.max(Number(node._taskTimingFinish || 0), finished);
            }
            const resultKind=task.executor==='comfy'
                ?mediaKindForUrls(taskImages,result?.videos?.length?'video':result?.audios?.length?'audio':result?.texts?.length?'text':'image')
                :(task.kind||'image');
            finalizeSmartPendingTask(node, task.taskId, taskImages, resultKind);
            if(result?.partial_failures?.length){
                const message = `${result.partial_failures.length} 个生成请求失败，成功图片已保留`;
                logTaskFailure(message, task);
                toast(message);
            }
            render({nodeIds:[node.id]});
            scheduleSave();
        } catch(e) {
            task = currentTask(task.taskId);
            if(!task) return;
            if(e && e.jimengPending && e.submitId){
                node.pendingTasks = smartPendingTasks(node).filter(item => item.taskId !== task.taskId);
                setNodeJimengPending(node, e);
                render({nodeIds:[node.id]});
                scheduleSave();
                return;
            }
            if(e && e.imageTaskRecover && e.recoverTaskId){
                task.failed = true;
                task.querying = false;
                task.recoverTaskId = e.recoverTaskId;
                task.providerId = e.providerId || task.providerId || providerIdForSmartTask(node, task);
                task.error = e.message || tr('smart.errRunFailed');
                node.running = false;
                node.pending = Math.max(1, smartPendingTasks(node).length);
                logTaskFailure(task.error, task);
                toast('任务未丢失，可稍后手动查询结果');
                render({nodeIds:[node.id]});
                scheduleSave();
                return;
            }
            node.pendingTasks = smartPendingTasks(node).filter(item => item.taskId !== task.taskId);
            node.pending = node.pendingTasks.length;
            if(!node.pending && smartPendingTasks(node).length === 0){
                delete node.pendingTasks;
                node.running = false;
            }
            failures.push(e);
            if(e?.terminalTask){
                const started = Number(e.startedAt || task.started_at || 0);
                const finished = Number(e.finishedAt || 0);
                if(started > 0){
                    const startedMs = started < 100000000000 ? started * 1000 : started;
                    node._taskTimingStart = Math.min(Number(node._taskTimingStart || startedMs), startedMs);
                }
                const finishedMs = finished > 0
                    ? (finished < 100000000000 ? finished * 1000 : finished)
                    : nowMs();
                node._taskTimingFinish = Math.max(Number(node._taskTimingFinish || 0), finishedMs);
                node._terminalFinishedAt = node._taskTimingFinish;
            }
            if(!e?.cancelledTask) logTaskFailure(e.message || tr('smart.errRunFailed'), task);
            if(e && typeof e === 'object') e.smartGenerationLogged = true;
            if(!e?.cancelledTask) toast((e.message || tr('smart.errRunFailed')).slice(0, 160));
            render({nodeIds:[node.id]});
            scheduleSave();
        }
    }));
    if(canvasId !== taskCanvasId) return;
    node = nodes.find(item => item.id === nodeId);
    if(!node) return;
    if(!failures.length && !node.pending && smartPendingTasks(node).length === 0){
        delete node.outpaintPreserve;
    }
    if(failures.length && (node.images || []).length && !node.pending && smartPendingTasks(node).length === 0){
        node.runFinishedAt = Number(node._taskTimingFinish || 0) || nowMs();
        node.runStartedAt = Number(node._taskTimingStart || 0) || node.runStartedAt || node.runFinishedAt;
        node.runElapsedMs = Math.max(0, node.runFinishedAt - node.runStartedAt);
        delete node._taskTimingStart;
        delete node._taskTimingFinish;
        delete node._terminalFinishedAt;
        render({nodeIds:[node.id]});
        scheduleSave();
    }
    if(failures.length && !(node.images || []).length){
        const failure = failures.find(error => !error?.cancelledTask) || failures[0];
        if(node.batchDetailOwnerId && failure?.cancelledTask) markSmartBatchScreenCancelled(node);
        else markSmartNodeFailed(node, failure?.message || tr('smart.errRunFailed'));
        render({nodeIds:[node.id]});
        scheduleSave();
        throw failure;
    }
}
function resumeSmartPendingTasks(){
    if(typeof recoverProductRetouchSubmissions === 'function')void recoverProductRetouchSubmissions();
    nodes.filter(node => smartPendingTasks(node).length).forEach(node => {
        // 恢复路径已经把错误留在节点；避免未处理的 Promise 拒绝打断页面。
        resumeSmartPendingNode(node).catch(error => console.warn('[Smart Canvas] 恢复任务失败', error));
    });
}
function updateSelectionBox(event){
    if(!selectionState) return;
    const clientX = Number(event?.clientX), clientY = Number(event?.clientY);
    if(!Number.isFinite(clientX) || !Number.isFinite(clientY)) return;
    selectionState.lastScreen = {x:clientX, y:clientY};
    const sx = selectionState.startScreen.x, sy = selectionState.startScreen.y;
    const x = Math.min(sx, clientX), y = Math.min(sy, clientY);
    selectionBox.style.display = 'block';
    selectionBox.style.left = `${x}px`;
    selectionBox.style.top = `${y}px`;
    selectionBox.style.width = `${Math.abs(clientX - sx)}px`;
    selectionBox.style.height = `${Math.abs(clientY - sy)}px`;
}
function beginSelectionGesture(event, options={}){
    const clientX = Number(event?.clientX), clientY = Number(event?.clientY);
    if(!Number.isFinite(clientX) || !Number.isFinite(clientY)) return false;
    clearSelectionClickGuard();
    if(document.activeElement?.blur) document.activeElement.blur();
    // 智能画布通常运行在 index.html 的 iframe 中。框选开始时如果只清掉
    // 输入框焦点，键盘焦点仍可能留在外层页面，导致后续 Del 不会到达本窗口。
    try { window.focus(); } catch(_) {}
    didPan = false;
    selectionState = {
        startScreen:{x:clientX, y:clientY},
        startWorld:screenToWorld(event),
        additive:Boolean(options.additive),
        subtractive:Boolean(options.subtractive),
        lastScreen:{x:clientX, y:clientY}
    };
    if(Number.isFinite(event?.pointerId)){
        selectionPointerId = event.pointerId;
        shell.setPointerCapture?.(event.pointerId);
    }else{
        selectionPointerId = null;
    }
    updateSelectionBox(event);
    return true;
}
function releaseSelectionPointer(){
    if(selectionPointerId === null) return;
    try { shell.releasePointerCapture?.(selectionPointerId); } catch(_) {}
    selectionPointerId = null;
}
function cancelSelectionGesture(){
    selectionState = null;
    selectionBox.style.display = 'none';
    releaseSelectionPointer();
}
function clearSelectionClickGuard(){
    selectionJustFinished = false;
    if(selectionJustFinishedTimer){
        clearTimeout(selectionJustFinishedTimer);
        selectionJustFinishedTimer = null;
    }
}
function markSelectionClickGuard(){
    clearSelectionClickGuard();
    selectionJustFinished = true;
    selectionJustFinishedTimer = setTimeout(() => {
        selectionJustFinished = false;
        selectionJustFinishedTimer = null;
    }, 500);
}
function finishSelection(event){
    if(!selectionState) return;
    const state = selectionState;
    const a = selectionState.startWorld;
    const b = screenToWorld(event);
    const minX = Math.min(a.x, b.x), minY = Math.min(a.y, b.y);
    const maxX = Math.max(a.x, b.x), maxY = Math.max(a.y, b.y);
    const hitIds = nodes.filter(node => {
        if(smartBatchIsHidden(node)) return false;
        const r = nodeRect(node);
        return r.x < maxX && r.x + r.width > minX && r.y < maxY && r.y + r.height > minY;
    }).map(n => n.id);
    const current = selectedNodeIds().filter(nodeId => nodes.some(node => node.id === nodeId));
    if(state.subtractive){
        const hitSet = new Set(hitIds);
        selectedIds = current.filter(id => !hitSet.has(id));
    } else if(state.additive){
        selectedIds = Array.from(new Set([...current, ...hitIds]));
    } else {
        selectedIds = hitIds;
    }
    selectedId = selectedIds.length === 1 ? selectedIds[0] : '';
    if(selectedIds.length <= 1) selectedIds = [];
    selectedImage = {nodeId:'', index:-1};
    selectionState = null;
    markSelectionClickGuard();
    selectionBox.style.display = 'none';
    releaseSelectionPointer();
    render();
}
function groupSelectedNodes(){
    if(!canvas || !collabCanMutateCanvas()) return;
    const ids = new Set(selectedNodeIds());
    const lookup = new Map(nodes.map(node => [node.id, node]));
    const existingMembers = new Set(nodes.filter(isSmartGroupNode)
        .flatMap(group => Array.isArray(group.items) ? group.items : []));
    const selected = [];
    for(const id of ids){
        const node = lookup.get(id);
        if(!node || isSmartGroupNode(node) || isSmartDrawingBoardNode(node) || existingMembers.has(id)) continue;
        if(isSmartImageNode(node) && !node.images?.length) continue;
        selected.push(node);
    }
    if(!selected.length){ toast('请选择要放入分组的节点'); return; }
    if(!selected.every(node => collabCanEditNode(node.id))) return;

    pushUndo();
    const bounds = XiaomeiSmartGroups.selectionBounds(selected.map(node => nodeRect(node)));
    const group = {
        id:uid('group'), type:'smart-group', ...bounds, title:'智能分组',
        items:[], images:[], created_at:Date.now()
    };
    nodes.push(group);
    for(const node of selected) addNodeToSmartGroup(group, node);
    arrangeSmartGroupMembers(group, {skipUndo:true});
    selectSmartCard(group.id);
    render();
    scheduleSave();
}

function ungroupNode(groupId){
    const group = nodes.find(node => node.id === groupId);
    if(!canvas || !group) return false;
    const smart = isSmartGroupNode(group);
    const allImages = Array.isArray(group.images) ? group.images : [];
    if(!smart && allImages.length < 2) return false;
    const members = smart ? smartGroupMembers(group) : [];
    if(!collabCanMutateCanvas() || ![group, ...members].every(node => collabCanEditNode(node.id))) return false;
    pushUndo();

    const media = smart ? allImages.filter(image => image?.url) : allImages;
    const layoutNode = group.collapsed ? {...group, collapsed:false} : group;
    const positions = media.length
        ? XiaomeiSmartGroups.standalonePositions(group, imageLayout(allImages, nodeScale(layoutNode), layoutNode), media, smart, thumbDisplaySize)
        : [];
    const placements = media.map((image, index) => {
        const child = {
            id:uid('smart'), type:SMART_UPLOAD_NODE_TYPE, ...positions[index], title:'Image',
            images:[smartGroupImageForStandaloneNode(image)], scale:MEDIA_NODE_DEFAULT_SCALE, created_at:Date.now()
        };
        inheritNodeMetaFromImage(child);
        clearDetachedRunInputRefs(child);
        return {child, origin:smart ? String(image?.[SMART_GROUP_ORIGIN_NODE_KEY] || '') : ''};
    });

    removeSmartGroupContainer(groupId);
    const restored = placements.map(item => item.child);
    smartAutoAvoidNewNodes(restored);
    nodes.push(...restored);
    for(const member of members){
        if(releaseSmartGroupMemberSize(member)) Object.assign(member, smartAutoAvoidNodePosition(member, member));
    }

    const liveIds = new Set(nodes.map(node => node.id));
    const memberIds = members.map(member => member.id).filter(id => liveIds.has(id));
    const graph = smartGroupGraph.expand({
        groupId, liveIds, members:memberIds,
        edges:canvas.connections || [],
        originals:smart && Array.isArray(group[SMART_GROUP_ORIGIN_CONNECTIONS_KEY]) ? group[SMART_GROUP_ORIGIN_CONNECTIONS_KEY] : [],
        placements:placements.map(item => ({id:item.child.id, origin:item.origin})),
        deleted:smartConnectionDeletionTombstones
    });
    rememberSmartConnectionDeletions(graph.removed);
    clearSmartConnectionDeletionTombstones(graph.added);
    canvas.connections = graph.edges;
    smartGroupGraph.updateInputIds(nodes, graph.retiredIds, graph.added);
    selectedIds = [...restored.map(node => node.id), ...memberIds];
    selectedId = selectedIds.length === 1 ? selectedIds[0] : '';
    selectedImage = {nodeId:'', index:-1};
    render();
    scheduleSave();
    return true;
}
function mergeImageNodesIntoGroup(sourceId, targetId){
    const source = nodes.find(n => n.id === sourceId);
    const target = nodes.find(n => n.id === targetId);
    if(!source || !target || source.id === target.id) return false;
    if(!(source.images || []).length || !(target.images || []).length) return false;
    const sourceImages = (source.images || []).map(img => stripImageGenerationMeta({...img}));
    const targetImages = (target.images || []).map(img => stripImageGenerationMeta(img));
    if(source.detachedFromNodeId === target.id && Number.isFinite(Number(source.detachedFromImageIndex))){
        const insertAt = Math.max(0, Math.min(targetImages.length, Math.round(Number(source.detachedFromImageIndex))));
        targetImages.splice(insertAt, 0, ...sourceImages);
        target.images = targetImages;
    } else {
        target.images = [...targetImages, ...sourceImages];
    }
    target.title = 'Group';
    if(!Number.isFinite(Number(target.scale)) || Number(target.scale) === MEDIA_NODE_DEFAULT_SCALE) target.scale = MEDIA_GROUP_DEFAULT_SCALE;
    delete target.w;
    delete target.h;
    rerouteSmartConnections(source.id, target.id);
    nodes = nodes.filter(n => n.id !== source.id);
    selectedIds = [];
    selectedId = target.id;
    selectedImage = {nodeId:'', index:-1};
    return true;
}
function addDraggedNodesToSmartGroup(draggedNodes, group){
    if(!isSmartGroupNode(group)) return false;
    const candidates = (draggedNodes || []).filter(node => node && node.id !== group.id);
    let changed = false;
    for(const node of candidates) changed = addNodeToSmartGroup(group, node) || changed;
    if(!changed) return false;
    arrangeSmartGroupMembers(group, {skipUndo:true});
    const single = candidates.length === 1 && nodes.some(node => node.id === candidates[0].id) ? candidates[0].id : '';
    selectSmartCard(single || group.id);
    return true;
}
function closeCreateMenu(options={}){
    if(createMenuCloseTimer){
        clearTimeout(createMenuCloseTimer);
        createMenuCloseTimer = 0;
    }
    createMenuGroupId = '';
    pendingPortCreate = null;
    if(!createMenu) return;
    const wasVisible = createMenu.classList.contains('open') || createMenu.classList.contains('is-closing');
    createMenu.classList.remove('open');
    const reducedMotion = typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const cleanup = () => {
        createMenu?.classList.remove('is-closing', 'create-menu-compact');
        createMenuCloseTimer = 0;
    };
    if(!wasVisible || options.immediate || reducedMotion){
        cleanup();
        return;
    }
    createMenu.classList.add('is-closing');
    createMenuCloseTimer = window.setTimeout(cleanup, 270);
}
function openCreateMenu(event, options={}){
    if(!createMenu || !collabCanMutateCanvas(true)) return;
    if(createMenuCloseTimer){
        clearTimeout(createMenuCloseTimer);
        createMenuCloseTimer = 0;
    }
    createMenu.classList.remove('is-closing');
    createMenuPoint = options.point || screenToWorld(event);
    createMenuGroupId = options.groupId || '';
    pendingPortCreate = options.pendingConnection || null;
    // 画布直接打开时使用横向卡片；从连接点拖拽松开时保留紧凑竖向菜单。
    const compact = Boolean(options.pendingConnection);
    createMenu.classList.toggle('create-menu-compact', compact);
    const cards = [...createMenu.querySelectorAll('[data-create-type]')];
    cards.forEach((card, index) => {
        card.style.setProperty('--create-index', index);
        card.style.setProperty('--create-reverse-index', cards.length - index - 1);
    });
    const w = compact ? 188 : Math.max(188, Math.min(776, window.innerWidth - 28));
    const columns = window.innerWidth <= 720 ? 2 : 3;
    const rows = Math.ceil(cards.length / columns);
    const fallbackHeight = compact ? Math.max(170, cards.length * 44 + 16) : 32 + rows * 118 + Math.max(0, rows - 1) * 9;
    createMenu.style.left = '0px';
    createMenu.style.top = '0px';
    createMenu.classList.add('open');
    const menuWidth = createMenu.offsetWidth || w;
    const menuHeight = createMenu.offsetHeight || fallbackHeight;
    const pointerX = Number(event?.clientX) || 0;
    const pointerY = Number(event?.clientY) || 0;
    const left = Math.max(14, Math.min(window.innerWidth - menuWidth - 14, pointerX + 10));
    const top = Math.max(14, Math.min(window.innerHeight - menuHeight - 14, pointerY + 10));
    createMenu.style.left = `${left}px`;
    createMenu.style.top = `${top}px`;
    refreshIcons();
}
function addCreatedNodeToMenuGroup(node){
    if(!node) return;
    const group = createMenuGroupId ? nodes.find(n => n.id === createMenuGroupId) : null;
    if(addNodeToSmartGroup(group, node)){
        // 通过分组小菜单新建的节点入组后自动整理（节点创建已压过 undo，这里不再重复）。
        arrangeSmartGroupMembers(group, {skipUndo:true});
        render();
        scheduleSave();
    }
}
function createNodeFromMenu(type){
    const p = createMenuPoint || viewportCenter();
    const groupId = createMenuGroupId;
    const pendingConnection = pendingPortCreate ? {...pendingPortCreate} : null;
    closeCreateMenu();
    let created = null;
    if(type === 'group') created = createSmartGroupNode(p.x - 170, p.y - 110);
    else if(type === 'prompt') created = createPromptNode(p.x - 158, p.y - 97);
    else if(type === 'agent') created = createAgentNode(p.x - SMART_AGENT_DEFAULT_WIDTH / 2, p.y - SMART_AGENT_DEFAULT_HEIGHT / 2);
    else if(type === 'expert-workflow') created = createAgentNode(p.x - 185, p.y - 180, {mode:'expert-workflow'});
    else if(type === 'table') created = createTableNode(p.x - 250, p.y - 180);
    else if(type === 'timeline') created = createTimelineNode(p.x - 260, p.y - 280);
    else if(type === 'loop') created = createLoopNode(p.x - 190, p.y - 270, {batchUiMode:'paired'});
    else if(type === 'camera') created = createCameraNode(p.x - Math.round(SMART_CAMERA_DEFAULT_WIDTH / 2), p.y - Math.round(SMART_CAMERA_DEFAULT_HEIGHT / 2));
    else if(type === 'compare') created = createCompareNode(p.x - Math.round(SMART_COMPARE_DEFAULT_WIDTH / 2), p.y - Math.round(SMART_COMPARE_DEFAULT_HEIGHT / 2));
    else if(type === 'color') created = createColorNode(p.x - Math.round(SMART_COLOR_DEFAULT_WIDTH / 2), p.y - Math.round(SMART_COLOR_DEFAULT_HEIGHT / 2));
    else if(type === 'paint') created = createPaintNodeAt(p);
    else if(type === 'video') created = createVideoNodeAt(p);
    else if(type === 'ai-render') created = createAiRenderNodeAt(p);
    else if(type === SMART_REPLICA_NODE_TYPE) created = window.SmartCanvasReplica.create(p);
    else if(type === 'product-fidelity') created = createProductFidelityNodeAt(p);
    else if(type === 'local-fusion') created = createLocalFusionNodeAt(p);
    else if(type === 'product-retouch') created = createProductRetouchNodeAt(p);
    else if(type === 'drawing-board') created = createDrawingBoardNodeAt(p);
    else if(type === 'comfyui') created = createComfyWorkflowNodeFromCatalog(p);
    else if(type === 'upload' || type === 'image') created = createImageNodeAt(p);
    createMenuGroupId = groupId;
    addCreatedNodeToMenuGroup(created);
    createMenuGroupId = '';
    if(created && pendingConnection && pendingConnection.fromId !== created.id){
        if(isSmartGroupNode(created) && !groupId && pendingConnection.fromPort === 'out'){
            const sourceIds = Array.isArray(pendingConnection.fromIds) && pendingConnection.fromIds.length
                ? pendingConnection.fromIds
                : [pendingConnection.fromId];
            const sourceNodes = sourceIds
                .map(sourceId => nodes.find(node => node.id === sourceId))
                .filter(node => node && !isSmartDrawingBoardNode(node));
            addDraggedNodesToSmartGroup(sourceNodes, created);
            render();
            scheduleSave();
            return created;
        }
        const fromIds = pendingConnection.fromPort === 'out'
            ? (Array.isArray(pendingConnection.fromIds) && pendingConnection.fromIds.length
                ? pendingConnection.fromIds
                : [pendingConnection.fromId])
            : [created.id];
        const toId = pendingConnection.fromPort === 'out' ? created.id : pendingConnection.fromId;
        let connected = 0;
        fromIds.filter(fromId => fromId !== toId).forEach(fromId => {
            const inputSlot = pendingConnection.fromPort === 'in'
                ? normalizeSmartNodeInputSlot(nodes.find(node => node.id === pendingConnection.fromId), pendingConnection.fromInputSlot)
                : '';
            if(connectInputNode(fromId, toId, inputSlot)) connected += 1;
        });
        if(connected){
            render();
            scheduleSave();
            if(fromIds.length > 1) toast(`已批量连接 ${connected} 个节点`);
        }
    }
    return created;
}
