window.addEventListener('paste', e => {
    // 图片编辑器打开时，粘贴是编辑器内部输入框的事，不能往被遮住的画布上贴节点或图片。
    if(imageEditModal.classList.contains('open')) return;
    if(!isEditableTarget(e.target)){
        const storedClipboard = nodeClipboardFromPasteEvent(e);
        if(storedClipboard?.nodes?.length){
            e.preventDefault();
            nodeClipboard = storedClipboard;
            pasteNodes();
            return;
        }
    }
    const files = [...(e.clipboardData?.files || [])].filter(isSupportedUploadFile);
    if(files.length){
        e.preventDefault();
        lastImagePasteAt = Date.now();
        handleFiles(files, selectedId, {deferComposer:true, showPastePreview:true});
        return;
    }
    // 素材库管理页「复制到画布」过来的素材：Ctrl+V 批量粘贴成图片节点
    if(!isEditableTarget(e.target) && pasteAssetsFromInbox()){
        e.preventDefault();
        return;
    }
    if(nodeClipboard?.nodes?.length && !isEditableTarget(e.target)){
        e.preventDefault();
        pasteNodes();
    }
});
