function applySmartKeyEffect(event, effect){
    if(effect.prevent) event.preventDefault();
    if(effect.type === 'clear-thumb'){
        smartThumbnailDrag.cancel();
        suppressSmartImageClicks();
    } else if(effect.type === 'arm-erase') smartConnectionEraser.hold(true);
    else if(effect.type === 'arm-rotate') isRKeyDown = true;
    else if(effect.type === 'close-editor') closeImageEditor();
    else if(effect.type === 'preview-step'){
        if(!smartPreview.stepVideo(effect.direction)) navigatePreviewImage(effect.direction);
    } else if(effect.type === 'toggle-assets') toggleAssetLibrary();
}
window.addEventListener('keydown', e => {
    const prelude = XiaomeiCanvasKeys.smartPrelude({
        key:e.key,
        editable:isEditableTarget(e.target),
        thumbDrag:smartThumbnailDrag.active(),
        imageEditor:imageEditModal.classList.contains('open'),
        previewMode:imageEditMode === 'preview'
    });
    prelude.effects.forEach(effect => applySmartKeyEffect(e, effect));
    if(prelude.skipChord) return;
    const action = XiaomeiHistoryKernel.chord({
        key:e.key, ctrl:e.ctrlKey, meta:e.metaKey, alt:e.altKey, shift:e.shiftKey, repeat:e.repeat
    }, {
        profile:'smart',
        plainEditable:isEditableTarget(e.target),
        commandEditable:isEditableTarget(e.target),
        modal:false,
        textSelected:Boolean(window.getSelection?.().toString()),
        canPaste:Boolean(nodeClipboard?.nodes?.length)
    });
    if(action?.type === 'ignore' || action?.type === 'zoom-preview'){
        e.preventDefault();
        if(action.type === 'zoom-preview') toggleZoomPreview();
        return;
    }
    if(action?.type === 'copy'){
        e.preventDefault();
        copySelectedNodes();
        return;
    }
    if(action?.type === 'paste-deferred'){
        const requestedAt = Date.now();
        setTimeout(() => {
            if(!XiaomeiHistoryKernel.pasteStillFresh(requestedAt, [lastImagePasteAt, lastNodePasteAt])) return;
            pasteNodes();
        }, action.delay);
        return;
    }
    if(action?.type === 'undo'){ e.preventDefault(); performUndo(); return; }
    if(action?.type === 'redo'){ e.preventDefault(); performRedo(); return; }
    if(action?.type === 'ungroup'){
        e.preventDefault();
        const ids = selectedIds.length ? selectedIds.slice() : (selectedId ? [selectedId] : []);
        const groupIds = [...new Set(ids.map(id => smartGroupContainingNode(id)?.id || id))];
        groupIds.map(ungroupNode).some(Boolean);
        return;
    }
    if(action?.type === 'group'){ e.preventDefault(); groupSelectedNodes(); return; }
    XiaomeiCanvasKeys.smartRemainder({
        key:e.key,
        command:e.ctrlKey || e.metaKey,
        alt:e.altKey,
        editable:isEditableTarget(e.target),
        repeat:e.repeat
    }).effects.forEach(effect => applySmartKeyEffect(e, effect));
});
