document.addEventListener('keydown', event => {
    if(event.key !== 'Escape' || !previewImageContextMenu || previewImageContextMenu.hidden) return;
    event.preventDefault();
    event.stopPropagation();
    closePreviewImageContextMenu();
}, true);
window.addEventListener('blur', closePreviewImageContextMenu);
document.getElementById('imageEditStage').addEventListener('wheel', event => {
    if(!cropState) return;
    event.preventDefault();
    event.stopPropagation();
    if(imageEditMode === 'preview'){
        if(smartPreview.stepVideo(event.deltaY > 0 ? 1 : -1)) return;
        smartPreview.wheel(event);
        return;
    }
    smartImageEditor.wheel(event);
}, {passive:false});
window.addEventListener('resize', () => {
    syncSmartNodeSettingsPanel();
    scheduleSmartCanvasImageResolution();
    if(composer.classList.contains('open')) positionComposerForNode(selectedNode());
    smartOcr.schedule();
    if(cropState) syncImageEditOverflow();
    if(imageEditModal.classList.contains('open') && imageEditMode === 'preview') smartPreview.syncFrame();
});
window.addEventListener('scroll', smartOcr.schedule, true);
window.addEventListener('studio-theme-change', event => applyTheme(event.detail?.theme || 'light'));
try {
    const apiChannel = new BroadcastChannel('studio-api');
    apiChannel.onmessage = async event => {
        if(event.data?.type === 'providers-changed' || event.data?.type === 'workflows-changed' || event.data?.type === 'comfy-instances-changed'){
            if(!sharedCanvasMode) await refreshSmartConfigFromSettings();
        }
        if(event.data?.type === 'asset_library_updated') handleAssetLibraryUpdatedMessage(event.data);
        if(event.data?.type === 'canvas_updated') handleCanvasUpdatedMessage(event.data);
        if(event.data?.type === 'prompt-cases-updated') handlePromptCasesUpdatedMessage(event.data);
    };
} catch(e) {}
try {
    const promptCaseChannel = new BroadcastChannel('studio-prompt-cases');
    promptCaseChannel.onmessage = event => {
        if(event.data?.type === 'prompt-cases-updated') handlePromptCasesUpdatedMessage(event.data);
    };
} catch(e) {}
window.addEventListener('focus', () => {
    if(!sharedCanvasMode && Date.now() - lastConfigRefreshAt > 1200) refreshSmartConfigFromSettings();
    if(!sharedCanvasMode && promptCaseIndexLoadedAt && Date.now() - promptCaseIndexLoadedAt > 3000) loadPromptCaseIndex();
});
window.addEventListener('message', event => {
    if(event.origin && event.origin !== location.origin) return;
    if(event.data?.type === 'soft-furnishing-inbox'){
        applySoftFurnishingInbox(event.data.payload || readSoftFurnishingInbox());
        return;
    }
    if(event.data?.type === 'comfy-workflow-inbox'){
        applyComfyWorkflowInbox(event.data.payload || readComfyWorkflowInbox());
        return;
    }
    if(event.data?.type === 'smart-workflow-inbox'){
        void importSmartWorkflowFromInbox(event.data.payload || null);
        return;
    }
    if(event.data?.type === 'studio-theme') applyTheme(event.data.theme || 'light');
    if(!sharedCanvasMode && (event.data?.type === 'providers-changed' || event.data?.type === 'workflows-changed' || event.data?.type === 'comfy-instances-changed')) refreshSmartConfigFromSettings();
    if(event.data?.type === 'asset_library_updated') handleAssetLibraryUpdatedMessage(event.data);
    if(event.data?.type === 'canvas_updated') handleCanvasUpdatedMessage(event.data);
    if(event.data?.type === 'prompt-case-apply') applyPromptCaseToCanvas(event.data.case);
    if(event.data?.type === 'prompt-cases-updated') handlePromptCasesUpdatedMessage(event.data);
    if(event.data?.type === 'studio-lang' && window.StudioI18n) {
        window.StudioI18n.set(event.data.lang || 'zh');
    }
});
window.addEventListener('studio-lang-change', () => {
    renderDynamicParams();
    renderInputThumbsRow(selectedNode());
    localAssetSidebar.render();
    if(document.getElementById('imageEditModal')?.classList.contains('open')){
        setImageEditMode(imageEditMode);
    }
    smartPromptLibrary.render();
    render();
});
initializeReferencePicker();
window.onload = async () => {
    // X6 引擎只读灰度（?engine=x6）。整条旧启动链在这里止步：不建 DOM、不开协作
    // socket、不恢复待执行任务、不写任何接口。回滚方式就是去掉地址里的 engine=x6。
    if(window.SmartCanvasEngineGray?.active){
        try {
            await window.SmartCanvasEngineGray.boot();
        } catch (error) {
            console.error('[xm-gray]', error);
        }
        return;
    }
    loadSmartWorkflowLibraryPreferences();
    loadCanvasViewPreferences();
    syncCanvasViewControls();
    initCollabUi();
    applyTheme(window.StudioTheme?.get?.() || 'light');
    smartPromptLibrary.loadLocal();
    if(window.StudioI18n) window.StudioI18n.apply();
    if(window.lucide) lucide.createIcons();
    const shareReady = await loadCanvasShareSession();
    if(sharedCanvasMode && !shareReady) return;
    connectAssetLibrarySyncSocket();
    await loadCanvas();
    smartCanvasReady = true;
    if(!sharedCanvasMode){
        void loadConfig().then(() => {
            resumeSmartPendingTasks();
            resumeJimengPendingNodes();
        });
    }
    connectCanvasCollaborationSocket();
    const softFurnishingInbox = pendingSoftFurnishingInbox || readSoftFurnishingInbox();
    pendingSoftFurnishingInbox = null;
    if(softFurnishingInbox) applySoftFurnishingInbox(softFurnishingInbox);
    const comfyWorkflowInbox = pendingComfyWorkflowInbox || readComfyWorkflowInbox();
    pendingComfyWorkflowInbox = null;
    if(comfyWorkflowInbox) applyComfyWorkflowInbox(comfyWorkflowInbox);
    const smartWorkflowInbox = readSmartWorkflowInbox();
    if(smartWorkflowInbox) void importSmartWorkflowFromInbox(smartWorkflowInbox);
    if(pendingPromptCaseApply){
        const pending = pendingPromptCaseApply;
        pendingPromptCaseApply = null;
        applyPromptCaseToCanvas(pending);
    }
    syncApiKindToggleVisibility();
    render();
    if(!sharedCanvasMode){
        void Promise.allSettled([smartPromptLibrary.refresh(), loadAssetLibrary(), loadPromptCaseIndex()]);
    }
};
window.addEventListener('beforeunload', () => {
    collabUnloading = true;
    clearTimeout(collabRetryTimer);
    clearInterval(collabHeartbeatTimer);
    try { collabSocket?.close(); } catch(_) {}
});
window.addEventListener('blur', () => {
    const owned = [...collabLocks.entries()]
        .filter(([,lock]) => String(lock?.member?.id || '') === String(collabMemberId))
        .map(([id]) => id);
    if(owned.length) collabReleaseLocks(owned);
});
